// OUAT Biology Mock Tests - Question Data
// 10 Tests x 30 Questions = 300 Questions

const mkQ = (id, topic, diff, q, opts, ans, exp) => ({id, topic, diff, q, opts, ans, exp});

// ── TEST 1 ──
const T1 = [
  mkQ(101,"Cell Biology","easy","Which of the following is CORRECTLY matched with the endomembrane system?",["Mitochondria – produces ATP","Chloroplast – converts light to energy","Golgi Apparatus – processes and packages proteins","Ribosome – translates mRNA"],2,"The endomembrane system includes ER, Golgi apparatus, lysosomes, and vacuoles. Mitochondria and chloroplasts are excluded as they have separate evolutionary origins."),
  mkQ(102,"Cell Biology","medium","INCORRECT statement about cell organelles:",["Lysosomes contain hydrolytic enzymes","Centrioles are absent in most mature plant cells","Ribosomes are absent in prokaryotes","Plastids are absent in animal cells"],2,"Ribosomes are present in ALL living cells — both prokaryotic (70S) and eukaryotic (80S). They are the site of protein synthesis in every cell."),
  mkQ(103,"Cell Biology","medium","The inner mitochondrial membrane contains:",["Digestive enzymes","ATP synthase and electron transport chain proteins","DNA polymerase","Ribosomal proteins only"],1,"The inner mitochondrial membrane houses the ETC complexes and ATP synthase (Complex V), which drives oxidative phosphorylation."),
  mkQ(104,"Cell Division","medium","During which phase of mitosis do chromosomes align at the equatorial (metaphase) plate?",["Prophase","Anaphase","Metaphase","Telophase"],2,"In Metaphase, chromosomes align at the metaphase plate (cell equator) and spindle fibres attach to kinetochores. This is used for karyotyping."),
  mkQ(105,"Cell Division","hard","In meiosis, the separation of homologous chromosomes occurs during:",["Anaphase I","Anaphase II","Metaphase I","Prophase II"],0,"Anaphase I separates homologous chromosomes (reduces ploidy). Anaphase II separates sister chromatids, similar to mitosis."),
  mkQ(106,"Cell Division","medium","Crossing over (exchange of genetic material) occurs between:",["Sister chromatids of the same chromosome","Non-homologous chromosomes","Non-sister chromatids of homologous chromosomes","Centromeres of different chromosomes"],2,"Crossing over during Prophase I occurs between non-sister chromatids of homologous chromosomes at points called chiasmata, generating genetic diversity."),
  mkQ(107,"Animal Physiology","easy","Digestion of proteins begins in which organ?",["Mouth","Oesophagus","Stomach","Small intestine"],2,"The enzyme pepsin (secreted as pepsinogen, activated by HCl) in the stomach begins protein digestion. Salivary amylase in the mouth digests starch, not proteins."),
  mkQ(108,"Animal Physiology","medium","The bicuspid (mitral) valve is situated between:",["Right atrium and right ventricle","Left atrium and left ventricle","Right ventricle and pulmonary artery","Left ventricle and aorta"],1,"The bicuspid (mitral) valve has two cusps and guards the left atrioventricular opening. The tricuspid valve is on the right side."),
  mkQ(109,"Animal Physiology","medium","Which hormone is secreted by the adrenal MEDULLA (not cortex)?",["Cortisol","Aldosterone","Adrenaline (Epinephrine)","Testosterone"],2,"Adrenal medulla secretes catecholamines: adrenaline and noradrenaline. Adrenal cortex secretes glucocorticoids (cortisol), mineralocorticoids (aldosterone), and sex steroids."),
  mkQ(110,"Animal Physiology","easy","Urea (the major nitrogenous waste) is synthesised in:",["Kidney","Spleen","Liver","Pancreas"],2,"Urea is synthesised in the liver via the urea (ornithine) cycle from NH₃ (from amino acid catabolism) and CO₂. It is then excreted by the kidneys."),
  mkQ(111,"Animal Physiology","medium","The 'lub' sound of the heartbeat is produced by closure of:",["Semilunar valves","Mitral and tricuspid (AV) valves","Aortic valve only","Pulmonary valve only"],1,"'Lub' (S1) = closure of mitral and tricuspid valves at the start of ventricular systole. 'Dub' (S2) = closure of aortic and pulmonary semilunar valves."),
  mkQ(112,"Animal Anatomy","medium","Which bone is part of the APPENDICULAR skeleton?",["Skull","Vertebral column","Femur","Sternum"],2,"The appendicular skeleton comprises limbs and girdles (pectoral + pelvic). Femur is the thigh bone. Skull, vertebral column, ribs, and sternum form the axial skeleton."),
  mkQ(113,"Genetics","easy","The process by which RNA is synthesised from a DNA template is called:",["Translation","Transcription","Replication","Transduction"],1,"Transcription: DNA → mRNA (done by RNA polymerase). Translation: mRNA → protein. Replication: DNA → DNA."),
  mkQ(114,"Genetics","medium","Turner syndrome is caused by which chromosomal constitution?",["47,XXY","47,XYY","45,X (XO)","47,XXX"],2,"Turner syndrome (45,X0): females with one X chromosome; features include short stature, webbed neck, no secondary sex characteristics, infertile."),
  mkQ(115,"Ecology","easy","Mutualism is the ecological interaction in which:",["One organism benefits, other is unaffected","Both organisms are harmed","Both organisms benefit","One organism benefits at the expense of the other"],2,"Mutualism: both species benefit (e.g., Rhizobium in legume roots — bacteria get nutrients, plant gets fixed nitrogen). Compare: commensalism (one benefits, other neutral), parasitism (one benefits, other harmed)."),
  mkQ(116,"Ecology","medium","According to the 10% energy law, if a plant has 10,000 J of energy, how much energy reaches the secondary consumer?",["1000 J","100 J","10 J","1 J"],1,"10% rule: Plants(10,000J) → Primary consumer(1,000J) → Secondary consumer(100J). Each trophic transfer loses ~90%."),
  mkQ(117,"Plant Physiology","easy","Which plant hormone is primarily responsible for artificial ripening of fruits?",["Auxin (IAA)","Gibberellin","Cytokinin","Ethylene"],3,"Ethylene is a gaseous plant hormone that accelerates fruit ripening. It is used commercially (ethephon) to ripen bananas, mangoes etc."),
  mkQ(118,"Plant Kingdom","easy","Which group of plants lacks vascular tissue (xylem and phloem)?",["Pteridophytes","Gymsomerms","Bryophytes","Angiosperms"],2,"Bryophytes (mosses, liverworts, hornworts) are non-vascular plants — called 'amphibians of the plant kingdom.' They need water for sexual reproduction."),
  mkQ(119,"Biochemistry","medium","The final electron acceptor in the mitochondrial electron transport chain is:",["NAD⁺","FAD","Cytochrome c","Molecular oxygen (O₂)"],3,"O₂ is the terminal electron acceptor in aerobic respiration. It accepts electrons and protons to form water: O₂ + 4H⁺ + 4e⁻ → 2H₂O."),
  mkQ(120,"Biotechnology","easy","Which enzyme is used to cut DNA at specific recognition sequences in recombinant DNA technology?",["DNA polymerase","RNA polymerase","Restriction endonuclease","DNA ligase"],2,"Type II restriction endonucleases cut DNA at specific palindromic sequences (e.g., EcoRI cuts at GAATTC). They are the molecular scissors of genetic engineering."),
  mkQ(121,"Neurology","medium","Which lobe of the cerebrum is primarily responsible for speech and voluntary motor activity?",["Occipital lobe","Parietal lobe","Frontal lobe","Temporal lobe"],2,"The frontal lobe contains the motor cortex and Broca's area (speech production). Occipital = vision, Parietal = somatosensory, Temporal = auditory processing."),
  mkQ(122,"Immunity","medium","Cell-mediated immunity is carried out by:",["B lymphocytes producing antibodies","T lymphocytes (cytotoxic T cells)","Plasma cells","Mast cells"],1,"Cell-mediated immunity (CMI) involves T lymphocytes — particularly cytotoxic T cells (CD8+) that kill infected cells directly, and helper T cells (CD4+) that coordinate immune responses."),
  mkQ(123,"Diseases","easy","Scurvy is caused by deficiency of:",["Vitamin D","Vitamin B12","Vitamin C (ascorbic acid)","Vitamin K"],2,"Vitamin C deficiency causes scurvy: bleeding gums, poor wound healing, joint pain. Vitamin C is essential for collagen synthesis."),
  mkQ(124,"Animal Kingdom","easy","Starfish and sea urchins belong to phylum:",["Mollusca","Arthropoda","Echinodermata","Annelida"],2,"Echinoderms (Echinodermata) are exclusively marine, spiny-skinned, show pentaradial symmetry in adults, and have a water vascular system."),
  mkQ(125,"Evolution","medium","Wings of butterfly and wings of birds are examples of:",["Homologous organs","Vestigial organs","Analogous organs","Both A and C"],2,"Analogous organs perform similar functions but have different evolutionary origins (structural origin differs). They indicate convergent evolution. Homologous organs have same origin but different functions."),
  mkQ(126,"Reproduction","easy","Fertilization of the ovum by the sperm normally occurs in the:",["Ovary","Uterus","Cervix","Ampullary region of the fallopian tube (oviduct)"],3,"Fertilization occurs in the ampullary-isthmic junction of the fallopian tube. The fertilized egg (zygote) then travels to the uterus for implantation."),
  mkQ(127,"Microbiology","easy","Cyanobacteria are also known as:",["Blue-green algae","Green algae","Red algae","Diatoms"],0,"Cyanobacteria (e.g., Anabaena, Nostoc) are prokaryotic, photosynthetic bacteria often called blue-green algae. They can fix atmospheric nitrogen and are used as biofertilizers."),
  mkQ(128,"Cell Biology","medium","The primary function of the Smooth Endoplasmic Reticulum (SER) is:",["Protein synthesis and secretion","Lipid synthesis and detoxification","Packaging of proteins in vesicles","Intracellular digestion"],1,"SER: lipid synthesis, steroid hormone synthesis, detoxification (especially in liver), storage of Ca²⁺. RER (with ribosomes): protein synthesis and secretion."),
  mkQ(129,"Animal Physiology","easy","The functional unit of the kidney responsible for urine formation is the:",["Glomerulus","Bowman's capsule","Nephron","Loop of Henle"],2,"The nephron is the structural and functional unit of the kidney. Each kidney has ~1 million nephrons. It performs filtration, reabsorption, and secretion."),
  mkQ(130,"Plant Physiology","easy","Opening and closing of stomata is regulated by:",["Root hair cells","Mesophyll cells","Guard cells","Epidermal cells"],2,"Guard cells change shape by altering their turgor pressure (via K⁺ pump and osmosis), controlling stomatal aperture for gas exchange and transpiration."),
];

// ── TEST 2 ──
const T2 = [
  mkQ(201,"Genetics","easy","In Mendel's dihybrid cross, the F2 phenotypic ratio is:",["1:2:1","3:1","9:3:3:1","1:1:1:1"],2,"Dihybrid cross F2 ratio = 9:3:3:1 (9 Round Yellow : 3 Round Green : 3 Wrinkled Yellow : 1 Wrinkled Green). This illustrates the Law of Independent Assortment."),
  mkQ(202,"Molecular Biology","easy","DNA double helix model (B-DNA) was proposed by:",["Griffith and Avery","Watson and Crick (1953)","Chargaff and Franklin","Meselson and Stahl"],1,"Watson and Crick (1953) proposed the double helix model using Rosalind Franklin's X-ray diffraction data and Chargaff's base pairing rules (A=T, G=C)."),
  mkQ(203,"Genetics","medium","A colorblind male (X^b Y) marries a carrier female (X^B X^b). What fraction of their SONS will be colorblind?",["1/4","1/2","3/4","All sons"],1,"Sons get Y from father and X from mother. Mother gives X^B or X^b with equal probability. So 1/2 of sons get X^b and are colorblind."),
  mkQ(204,"Molecular Biology","easy","Which RNA molecule carries amino acids to the ribosome during protein synthesis?",["mRNA","rRNA","tRNA","hnRNA"],2,"tRNA is the adapter molecule — it has an anticodon that pairs with mRNA codons, and carries the corresponding amino acid to the ribosome."),
  mkQ(205,"Genetics","medium","Huntington's chorea (disease) shows which pattern of inheritance?",["Autosomal recessive","X-linked recessive","Autosomal dominant","Mitochondrial inheritance"],2,"Huntington's is autosomal dominant — one defective allele is sufficient to cause disease. It shows late onset (40s-50s) and involves trinucleotide CAG repeats in the HTT gene."),
  mkQ(206,"Molecular Biology","medium","Semiconservative DNA replication was experimentally proved by:",["Watson and Crick","Meselson and Stahl using ¹⁵N/¹⁴N isotopes","Griffith's transformation experiment","Hershey and Chase phage experiment"],1,"Meselson-Stahl (1958): grew bacteria in ¹⁵N (heavy), switched to ¹⁴N. After one generation, hybrid (¹⁵N-¹⁴N) DNA confirmed semiconservative replication."),
  mkQ(207,"Genetics","easy","Which condition is caused by the chromosomal constitution 47,XXY?",["Turner syndrome","Down syndrome","Klinefelter syndrome","Patau syndrome"],2,"Klinefelter syndrome (47,XXY): males with extra X chromosome; features include tall stature, gynecomastia, infertility, testicular atrophy."),
  mkQ(208,"Molecular Biology","easy","The complementary base pairing in DNA involves which type of bond?",["Covalent bonds","Ionic bonds","Hydrogen bonds","Phosphodiester bonds"],2,"Hydrogen bonds hold complementary bases: A=T (2 H-bonds), G≡C (3 H-bonds). The sugar-phosphate backbone is linked by covalent phosphodiester bonds."),
  mkQ(209,"Genetics","medium","An AaBb organism crossed with aabb (to determine genotype) is called:",["Monohybrid cross","Back cross","Test cross","Dihybrid cross"],2,"A test cross involves crossing an unknown genotype individual with a homozygous recessive (aabb) individual to determine the genotype."),
  mkQ(210,"Molecular Biology","medium","Okazaki fragments are synthesized on which strand during DNA replication?",["Leading strand (continuously)","Lagging strand (discontinuously)","Both strands equally","Template strand only"],1,"DNA synthesis is only 5'→3'. The lagging strand template runs 3'→5', so it's synthesized in short Okazaki fragments, later joined by DNA ligase."),
  mkQ(211,"Genetics","hard","Epistasis is defined as:",["Incomplete dominance of one allele","Interaction between alleles of the SAME gene","One gene pair masking expression of another (non-allelic) gene pair","Linkage between genes"],2,"Epistasis = interaction between genes at different loci where one gene masks another. Example: 9:7 ratio in sweet pea flower color (two genes needed for pigment production)."),
  mkQ(212,"Molecular Biology","easy","The anticodon is located on which RNA molecule?",["mRNA","tRNA","rRNA","hnRNA"],1,"tRNA has a cloverleaf structure with an anticodon loop (3 nucleotides complementary to mRNA codon) and an amino acid attachment site (CCA-3' end)."),
  mkQ(213,"Genetics","medium","Frameshift mutations result from:",["Base substitution (point mutation)","Insertion or deletion of nucleotide(s) not in multiples of 3","Silent mutations","Transitions and transversions"],1,"Frameshift mutations: insertion/deletion of nucleotides alters the reading frame of all downstream codons, causing completely different amino acids or premature stop codons."),
  mkQ(214,"Molecular Biology","medium","The promoter sequence in a gene is:",["The coding sequence (exons)","The region where RNA polymerase binds to initiate transcription","The terminator sequence","An intron"],1,"The promoter is a regulatory DNA sequence upstream of the gene where RNA polymerase (and transcription factors) bind to initiate transcription. In prokaryotes: -10 (TATA box) and -35 regions."),
  mkQ(215,"Genetics","easy","How many chromosomes does a normal human gamete (sperm or egg) contain?",["46","23","48","44"],1,"Normal human somatic cells: 46 (2n). After meiosis, gametes contain 23 (n = haploid). Fertilization restores 2n=46."),
  mkQ(216,"Genetics","medium","Sickle-cell anemia is caused by:",["Deletion of three nucleotides (frameshift)","Single nucleotide substitution (A→T) in the 6th codon of β-globin gene","Chromosomal translocation","Gene duplication"],1,"In sickle-cell anemia, a single base change (GAG→GTG) changes glutamic acid to valine at position 6 of the β-globin chain, causing HbS (sickle hemoglobin). It is autosomal recessive."),
  mkQ(217,"Molecular Biology","easy","In eukaryotic cells, introns are:",["Coding sequences that appear in mature mRNA","Non-coding sequences removed from pre-mRNA by splicing","The same as exons","Present only in mitochondrial genes"],1,"Introns are non-coding intervening sequences in eukaryotic genes. They are transcribed into pre-mRNA but removed (spliced out) before translation. Exons = expressed sequences."),
  mkQ(218,"Genetics","medium","The genotypic ratio of a monohybrid cross Aa × Aa is:",["3:1","1:2:1 (AA:Aa:aa)","1:1","2:1"],1,"Aa × Aa gives genotypes: AA(1) : Aa(2) : aa(1) = 1:2:1. The phenotypic ratio is 3:1 (3 dominant : 1 recessive), but genotypic is 1:2:1."),
  mkQ(219,"Genetics","medium","Which phenomenon results from non-disjunction during meiosis?",["Gene mutation","Silent mutation","Aneuploidy (abnormal chromosome number)","Gene inversion"],2,"Non-disjunction = failure of homologous chromosomes (meiosis I) or sister chromatids (meiosis II) to separate, producing n+1 or n-1 gametes → trisomy or monosomy."),
  mkQ(220,"Molecular Biology","medium","The enzyme that joins Okazaki fragments during DNA replication is:",["DNA polymerase I (removes primers) + DNA ligase (joins)","Helicase","Primase","Topoisomerase"],0,"DNA Pol I removes RNA primers and fills gaps with DNA. DNA ligase then covalently joins the nicks between Okazaki fragments."),
  mkQ(221,"Genetics","medium","Phenotypic ratio in incomplete dominance for Rr × Rr cross (where Rr = pink)?",["3:1","1:2:1 (Red:Pink:White)","1:1","9:3:3:1"],1,"With incomplete dominance: RR=Red, Rr=Pink, rr=White. Rr×Rr gives 1RR:2Rr:1rr = phenotypic ratio 1:2:1 (unlike dominant–recessive 3:1)."),
  mkQ(222,"Molecular Biology","easy","Which nucleotide base is present in RNA but NOT in DNA?",["Adenine","Guanine","Thymine","Uracil"],3,"RNA contains uracil (U) instead of thymine (T). Both pair with adenine, but thymine has an extra methyl group. DNA uses thymine for stability."),
  mkQ(223,"Genetics","easy","Which DNA technology is used to identify individuals from small biological samples (forensic science)?",["PCR","DNA fingerprinting (VNTR/STR analysis)","Gene therapy","Gel electrophoresis"],1,"DNA fingerprinting uses Variable Number Tandem Repeats (VNTRs) or Short Tandem Repeats (STRs) — regions that vary between individuals — to create unique DNA profiles."),
  mkQ(224,"Molecular Biology","hard","The CRISPR-Cas9 system uses guide RNA (gRNA) to:",["Repair damaged DNA","Direct Cas9 endonuclease to a specific genomic location for cutting","Amplify DNA sequences","Synthesize proteins"],1,"CRISPR-Cas9: gRNA (~20 nt) matches the target DNA sequence; Cas9 creates a double-strand break. The cell's repair machinery can introduce mutations (gene knockout) or incorporate new sequences."),
  mkQ(225,"Genetics","medium","Polygenic inheritance (e.g., skin color, height) results in:",["Discrete Mendelian ratios","Continuous phenotypic variation with normal distribution","Complete dominance","Epistasis"],1,"Polygenic traits are controlled by multiple genes, each with a small additive effect → continuous bell-curve distribution in the population."),
  mkQ(226,"Genetics","medium","INCORRECT about meiosis:",["It produces haploid cells from diploid cells","It occurs in gonads (testes/ovaries)","It maintains the chromosome number across generations","It introduces genetic variation via crossing over"],2,"Meiosis REDUCES the chromosome number (2n→n). It is mitosis that maintains the chromosome number. Meiosis followed by fertilization maintains the species' 2n number across generations."),
  mkQ(227,"Molecular Biology","medium","Reverse transcriptase (found in retroviruses) synthesises:",["DNA from RNA template","RNA from DNA template","Protein from mRNA","DNA from DNA template"],0,"Reverse transcriptase: RNA → cDNA (complementary DNA). It is central to HIV replication and to creating cDNA libraries in biotechnology."),
  mkQ(228,"Genetics","easy","Down syndrome (Trisomy 21) is associated with:",["Deletion of chromosome 21","Trisomy of chromosome 21 (3 copies)","Monosomy of chromosome 21","Inversion in chromosome 21"],1,"Down syndrome: 3 copies of chromosome 21 (47 chromosomes). Features: intellectual disability, flat face, slanted eyes, single palmar crease, heart defects."),
  mkQ(229,"Genetics","medium","In a test cross of AaBb with aabb, if 4 phenotypic classes appear in roughly equal proportion, genes are:",["Linked and close together","Sex-linked","On non-homologous (independently assorting) chromosomes","All from maternal chromosome"],2,"Equal 1:1:1:1 ratio in test cross indicates independent assortment (genes on different chromosomes). Linkage would show parental types in excess."),
  mkQ(230,"Molecular Biology","medium","The 'wobble hypothesis' proposed by Crick explains:",["Base pairing in DNA","Why 61 sense codons can be read by fewer tRNA anticodons","How replication is semiconservative","The colinearity of gene and protein"],1,"Wobble: the 3rd position of the anticodon can pair flexibly with multiple codons (wobble base pairing), allowing fewer tRNAs (~45) to recognise 61 sense codons."),
];

// ── TEST 3 ──
const T3 = [
  mkQ(301,"Classification","medium","Which of the following is NOT a kingdom in Whittaker's Five-Kingdom system?",["Monera","Protista","Archaea (as separate kingdom)","Fungi"],2,"Whittaker's five kingdoms: Monera, Protista, Fungi, Plantae, Animalia. Archaebacteria are included in Monera in the 5-kingdom system. They are a separate domain in 3-domain system."),
  mkQ(302,"Animal Kingdom","easy","Which class of vertebrates has a two-chambered heart?",["Amphibia","Reptilia","Pisces (fish)","Aves"],2,"Fish (Pisces) have a 2-chambered heart (1 atrium + 1 ventricle) — single circulation. Amphibia/Reptilia: 3-chambered. Birds/Mammals: 4-chambered — double circulation."),
  mkQ(303,"Animal Kingdom","medium","Which phylum shows radial symmetry in adults and contains exclusively marine organisms?",["Porifera","Platyhelminthes","Echinodermata","Annelida"],2,"Echinoderms (sea stars, sea urchins, sea cucumbers) are exclusively marine, show pentaradial symmetry in adults (bilateral in larvae), and have a water vascular system."),
  mkQ(304,"Animal Kingdom","easy","Which animal has an OPEN circulatory system?",["Earthworm","Cockroach","Frog","Human"],1,"Cockroaches (Arthropoda) have an open circulatory system — blood (hemolymph) is not always in closed vessels but fills body cavities (haemocoel). Earthworm, frog, and humans have closed systems."),
  mkQ(305,"Animal Kingdom","easy","The phylum that includes all animals with jointed appendages (legs, wings, antennae) is:",["Mollusca","Arthropoda","Annelida","Echinodermata"],1,"Arthropoda is the largest animal phylum: jointed appendages, exoskeleton of chitin, segmented body. Includes insects, spiders, crustaceans, centipedes."),
  mkQ(306,"Animal Kingdom","medium","Flame cells are the excretory structures found in:",["Annelida (nephridia)","Platyhelminthes (flatworms)","Insects (Malpighian tubules)","Vertebrates (kidneys)"],1,"Flame cells (protonephridia) are primitive excretory cells in Platyhelminthes (planarians, flukes). They have a tuft of cilia that 'flicker' like a flame."),
  mkQ(307,"Classification","easy","Viruses are not included in any kingdom because:",["They are too small to classify","They are acellular (not made of cells)","They are non-living in all situations","They are bacteria"],1,"Viruses are acellular entities with either DNA or RNA enclosed in a protein coat (capsid). They lack cellular organization, metabolism, and can only reproduce inside host cells."),
  mkQ(308,"Microbiology","easy","Which bacterium forms root nodules in legume plants and fixes atmospheric nitrogen?",["Vibrio cholerae","Rhizobium","Clostridium botulinum","Salmonella"],1,"Rhizobium forms mutualistic root nodules in legumes (pea, bean, soybean). It reduces N₂ to NH₃ via nitrogenase enzyme. This symbiosis supplies fixed nitrogen to the plant."),
  mkQ(309,"Fungi","easy","Which fungus is used in the production of Penicillin antibiotics?",["Aspergillus niger","Mucor","Penicillium notatum","Agaricus campestris"],2,"Alexander Fleming (1929) discovered penicillin produced by Penicillium notatum. It inhibits bacterial cell wall synthesis (peptidoglycan cross-linking)."),
  mkQ(310,"Animal Kingdom","medium","Which of the following is a pseudocoelomate (body cavity NOT lined by mesoderm)?",["Earthworm","Ascaris (roundworm)","Starfish","Cockroach"],1,"Ascaris (Nematoda) is pseudocoelomate — the body cavity is not lined by mesoderm. True coelomates (earthworm, insects, vertebrates) have mesoderm-lined body cavities."),
  mkQ(311,"Animal Kingdom","medium","Malpighian tubules are the excretory organs of:",["Annelids","Platyhelminthes","Insects (Arthropoda)","Mollusca"],2,"Malpighian tubules in insects: finger-like outgrowths of the alimentary canal that collect nitrogenous waste from haemolymph and discharge into the hindgut as uric acid."),
  mkQ(312,"Classification","easy","Amoeba belongs to which kingdom?",["Monera","Fungi","Protista","Animalia"],2,"Amoeba is a unicellular eukaryote classified under Kingdom Protista. It moves and feeds via pseudopodia. Monera = prokaryotes (bacteria, cyanobacteria)."),
  mkQ(313,"Animal Kingdom","medium","Which vertebrate class lays amniotic eggs AND has dry scaly skin?",["Amphibia","Reptilia","Pisces","Aves"],1,"Reptiles: amniotic eggs (with extraembryonic membranes), dry scaly skin (keratin scales), ectothermic. This was key adaptation to fully terrestrial life."),
  mkQ(314,"Animal Kingdom","easy","The largest phylum in the Animal Kingdom (in terms of species number) is:",["Chordata","Mollusca","Arthropoda","Nematoda"],2,"Arthropoda has over 1 million described species (~80% of all animal species). It includes insects, which account for most of these."),
  mkQ(315,"Fungi","medium","Lichens are a symbiotic association between:",["Two types of algae","Fungus and bacteria","Fungus (mycobiont) and alga/cyanobacterium (photobiont)","Moss and fungus"],2,"Lichens: fungus provides physical protection and absorbs water/minerals; alga/cyanobacterium performs photosynthesis providing food. A classic mutualistic symbiosis."),
  mkQ(316,"Animal Kingdom","easy","Which feature is UNIQUE to mammals and distinguishes them from all other vertebrates?",["Warm-blooded","Four-chambered heart","Mammary glands for nursing young + hair/fur","Internal fertilization"],2,"Mammals: defined by mammary glands (milk production), hair/fur, three middle ear bones (malleus, incus, stapes), and live birth (mostly). Birds also have 4-chambered hearts and are warm-blooded."),
  mkQ(317,"Animal Kingdom","medium","Which phylum has a water canal (water vascular) system used for locomotion and feeding?",["Mollusca","Arthropoda","Echinodermata","Coelenterata"],2,"Echinoderms have a water vascular system: tube feet (podia) are hydraulically operated for movement, prey capture, and gas exchange."),
  mkQ(318,"Microbiology","medium","Archaebacteria differ from Eubacteria primarily in:",["Size and shape","Ribosome type","Cell wall composition (ether-linked lipids, no peptidoglycan)","Presence of DNA"],2,"Archaebacteria have unique ether-linked lipids in their membranes, distinct cell walls (no peptidoglycan), and thrive in extreme environments (hot springs, salty lakes, anaerobic marshes)."),
  mkQ(319,"Animal Kingdom","medium","INCORRECT statement about Aves (birds):",["They are homeothermic (warm-blooded)","They have a four-chambered heart","They are oviparous","They have teeth in adult birds for crushing food"],3,"Modern birds (Aves) lack teeth — they have a beak/bill. The ancestor Archaeopteryx had teeth, but modern birds lost them. All other options are correct for birds."),
  mkQ(320,"Animal Kingdom","easy","Nematocysts (stinging cells used for prey capture) are characteristic of phylum:",["Porifera","Cnidaria (Coelenterata)","Platyhelminthes","Echinodermata"],1,"Cnidaria (jellyfish, hydra, corals): cnidocytes contain coiled, explosive nematocysts that inject venom into prey. They also show alternation of polyp and medusa stages."),
  mkQ(321,"Animal Kingdom","medium","Metameric segmentation (true segmentation where segments are serially repeated) is a feature of:",["Platyhelminthes","Mollusca","Annelida","Arthropoda only"],2,"Annelida (earthworms, leeches) shows true metamerism — each body segment contains similar organs. This is distinct from the pseudo-segmentation seen in some other groups."),
  mkQ(322,"Classification","easy","Scientific name of tiger is Panthera tigris. In this, Panthera is the:",["Species name","Genus name","Family name","Order name"],1,"In binomial nomenclature (Linnaeus): the first word = genus (capitalised), second word = species (lowercase). Both are italicised or underlined."),
  mkQ(323,"Microbiology","medium","E. coli is extensively used in research because it:",["Is pathogenic to humans","Has the largest genome among bacteria","Is easy to culture, rapid growth, well-characterized genetics","Produces many useful secondary metabolites"],2,"E. coli (Escherichia coli) is the 'workhorse' of molecular biology: rapid doubling time (20 min), easy to culture, well-known genetics, easily transformed with foreign DNA."),
  mkQ(324,"Animal Kingdom","medium","The 'coelom' in animals is a body cavity that is:",["Between body wall and gut, lined by mesoderm","Filled with blood","The digestive tract","Between ectoderm and mesoderm"],0,"Coelom = fluid-filled cavity between the body wall and gut, derived from and lined by mesoderm. It provides a compartment for organ development and protects internal organs."),
  mkQ(325,"Fungi","medium","Which fungal product is used as an immunosuppressant to prevent organ transplant rejection?",["Penicillin","Cyclosporin A (from Trichoderma polysporum)","Griseofulvin","Amphotericin B"],1,"Cyclosporin A from Trichoderma polysporum inhibits T-cell activation (calcineurin pathway), used to prevent rejection of transplanted organs."),
  mkQ(326,"Animal Kingdom","easy","Which phylum contains hermaphroditic animals that have a saddle-like structure (clitellum)?",["Arthropoda","Annelida","Mollusca","Platyhelminthes"],1,"Earthworms (Annelida) are hermaphrodites with a clitellum — a band of glandular tissue that secretes the cocoon for eggs. They also have nephridia for excretion."),
  mkQ(327,"Classification","medium","Which kingdom contains organisms that obtain nutrition by absorption (saprotrophic) through extracellular digestion?",["Plantae","Animalia","Fungi","Protista"],2,"Fungi are heterotrophs that secrete digestive enzymes outside (extracellular digestion) and absorb the products. They are important decomposers. Cell wall = chitin."),
  mkQ(328,"Animal Kingdom","medium","Balanoglossus belongs to which group and shows what structure similar to notochord?",["Echinodermata — true notochord","Hemichordata — stomochord in collar region","Chordata — notochord throughout life","Platyhelminthes — proboscis"],1,"Balanoglossus (acorn worm) is Hemichordata. It has a stomochord (a forward extension of the gut, NOT a true notochord) in its collar region — considered a precursor to the notochord."),
  mkQ(329,"Microbiology","easy","Comma-shaped bacteria belong to which group?",["Coccus","Bacillus","Spirillum","Vibrio"],3,"Bacterial shapes: Coccus = spherical, Bacillus = rod-shaped, Spirillum = spiral/helical, Vibrio = comma-shaped (e.g., Vibrio cholerae causes cholera)."),
  mkQ(330,"Animal Kingdom","medium","INCORRECT about Porifera (sponges):",["They have a water canal system","Water enters through ostia and leaves via osculum","They are multicellular","They show bilateral symmetry"],3,"Porifera (sponges) are asymmetrical (no definite symmetry) or show radial symmetry — NOT bilateral. They are the simplest multicellular animals."),
];

// ── TEST 4 ──
const T4 = [
  mkQ(401,"Plant Kingdom","easy","Which of the following is the defining feature of angiosperms that distinguishes them from gymnosperms?",["Presence of roots","Presence of vascular tissue","Seeds enclosed in a fruit (ovules in ovary)","Alternation of generations"],2,"Angiosperms (flowering plants): ovules enclosed in an ovary that develops into fruit after fertilization. Gymnosperms have naked seeds (ovules on megasporophylls, not in an ovary)."),
  mkQ(402,"Plant Physiology","medium","Photosynthesis occurs in which parts of the chloroplast?",["Outer membrane only","Stroma (Calvin cycle) and thylakoid membranes (light reactions)","Inner membrane only","Intermembrane space"],1,"Light-dependent reactions: thylakoid membranes (photosystems I and II, ETC, ATP synthase). Light-independent (Calvin cycle): stroma."),
  mkQ(403,"Plant Anatomy","medium","The type of meristem found between the node and internode in grasses (allows growth after cutting) is:",["Apical meristem","Lateral meristem (cambium)","Intercalary meristem","Secondary meristem"],2,"Intercalary meristem (at base of internodes) allows grasses to regrow after grazing or mowing. This is why lawns regrow after cutting."),
  mkQ(404,"Plant Physiology","medium","In C₄ plants (like sugarcane and maize), the primary CO₂ acceptor is:",["RuBP (Ribulose 1,5-bisphosphate)","OAA (Oxaloacetate) via PEP carboxylase","ATP","NADPH"],1,"C₄ plants: CO₂ is first fixed by PEP carboxylase (using PEP) in mesophyll cells to form OAA (C₄ compound). CO₂ is concentrated in bundle sheath cells for the Calvin cycle."),
  mkQ(405,"Plant Kingdom","easy","Which statement is TRUE about gymnosperms?",["They produce flowers and fruits","Their ovules are enclosed in an ovary","Their seeds are naked (not enclosed in fruit)","They are non-vascular plants"],2,"Gymnosperms (naked seed plants — Pinus, Cycas, Gnetum): ovules are borne on megasporophylls/cone scales, not enclosed in an ovary. Hence no fruit formation."),
  mkQ(406,"Plant Anatomy","medium","Companion cells in phloem are closely associated with which cell type?",["Xylem vessels","Sieve tube elements","Sclerenchyma fibres","Guard cells"],1,"Companion cells (nucleated) are metabolically active and support enucleate sieve tube elements in phloem. They are connected by plasmodesmata and assist in loading/unloading sugars."),
  mkQ(407,"Plant Physiology","medium","Which plant hormone promotes seed dormancy and stomatal closure during water stress?",["Gibberellin (breaks dormancy)","Cytokinin (promotes growth)","Abscisic acid (ABA)","Auxin (IAA)"],2,"Abscisic acid (ABA) = 'stress hormone.' It induces seed dormancy, promotes stomatal closure (to reduce water loss), promotes leaf senescence and abscission."),
  mkQ(408,"Plant Kingdom","medium","In the alternation of generations in plants, the sporophyte:",["Is always the dominant phase","Is haploid and produces spores","Is diploid (2n) and produces spores by meiosis","Is dominant only in bryophytes"],2,"Sporophyte = diploid (2n) generation that produces haploid (n) spores by meiosis. Gametophyte = haploid, produces gametes. In bryophytes: gametophyte dominant. In vascular plants: sporophyte dominant."),
  mkQ(409,"Plant Anatomy","medium","The Casparian strip in the endodermis of roots forces water to pass through:",["The intercellular spaces (apoplast)","The cell wall around Casparian strip","Through the cytoplasm of endodermal cells (symplast)","Through the xylem directly"],2,"The Casparian strip (suberin-impregnated band in endodermal cell walls) blocks apoplastic flow, forcing water and dissolved minerals to cross the selectively permeable endodermal cell membrane (symplast) before entering xylem."),
  mkQ(410,"Plant Physiology","easy","Which element is the central atom of chlorophyll (essential for its synthesis)?",["Calcium (Ca)","Magnesium (Mg)","Phosphorus (P)","Iron (Fe)"],1,"Chlorophyll (a and b) contains a porphyrin ring with Mg²⁺ at the centre. Iron (Fe) is needed for haemoglobin. Phosphorus is in ATP, DNA, and phospholipids."),
  mkQ(411,"Plant Kingdom","easy","Root-like structures (rhizoids) for anchorage and water absorption are found in:",["Pteridophytes","Gymnosperms","Bryophytes","Angiosperms"],2,"Bryophytes have rhizoids (single-celled or simple filaments) — NOT true roots with vascular tissue. True roots first appear in pteridophytes."),
  mkQ(412,"Plant Physiology","medium","The light-independent reactions (Calvin cycle/C3 cycle) of photosynthesis take place in:",["Thylakoid membrane (grana)","Stroma of chloroplast","Outer chloroplast envelope","Cytoplasm"],1,"Calvin cycle occurs in the stroma where CO₂ is fixed by RuBisCO using ATP and NADPH (produced in light reactions in thylakoids)."),
  mkQ(413,"Plant Physiology","medium","Vernalisation promotes flowering in plants by exposing them to:",["High temperature","Low temperature (cold treatment)","High light intensity","Short day length only"],1,"Vernalisation = promotion of flowering by cold treatment. Wheat, rye, carrot (biennials) need a cold winter to flower in spring. It prevents premature flowering."),
  mkQ(414,"Plant Anatomy","medium","Which meristematic tissue is responsible for secondary growth (increase in girth) in dicots?",["Apical meristem","Intercalary meristem","Vascular cambium (lateral meristem)","Primary meristem"],2,"Vascular cambium (a lateral meristem) produces secondary xylem (wood) outward and secondary phloem inward, causing increase in girth. Cork cambium produces bark."),
  mkQ(415,"Plant Kingdom","easy","Ferns belong to which group?",["Bryophytes (non-vascular)","Pteridophytes (seedless vascular)","Gymnosperms","Angiosperms"],1,"Pteridophytes (ferns, Selaginella, Equisetum): first vascular plants without seeds. They reproduce via spores. The sporophyte is dominant; gametophyte = small prothallus."),
  mkQ(416,"Plant Physiology","medium","Transpiration pull is the primary mechanism for ascent of sap. It depends on:",["Root pressure pushing water up","Capillary action alone","Cohesion-tension created by evaporation at leaves pulling water up via xylem","Osmotic pressure of phloem"],2,"Cohesion-tension theory (Dixon & Joly): transpiration at leaves creates tension (negative pressure), pulling a continuous water column up xylem. Cohesion of water molecules (H-bonds) maintains the column."),
  mkQ(417,"Plant Physiology","easy","Which enzyme catalyses carbon dioxide fixation in C₃ plants (the Calvin cycle)?",["PEP carboxylase","RuBisCO (Ribulose-1,5-bisphosphate carboxylase/oxygenase)","Pyruvate carboxylase","Hexokinase"],1,"RuBisCO is the most abundant enzyme on Earth. It catalyses: CO₂ + RuBP → 2 molecules of 3-PGA (3-phosphoglycerate). In C₄ plants, PEP carboxylase performs initial CO₂ fixation."),
  mkQ(418,"Plant Physiology","medium","What is the primary effect of cytokinin on plants?",["Promotes root elongation (cell elongation)","Induces senescence (ageing)","Promotes cell division (cytokinesis) and delays senescence","Inhibits seed germination"],2,"Cytokinins (e.g., kinetin, zeatin): promote cell division (by promoting cytokinesis), delay leaf senescence (stay-green effect), promote lateral bud growth. Synthesised in roots, translocated to shoots."),
  mkQ(419,"Plant Kingdom","medium","The dominant generation in liverworts (bryophytes like Marchantia) is:",["Sporophyte (2n)","Gametophyte (n) — the familiar thallus","Both equally dominant","Neither; they alternate with equal dominance"],1,"In bryophytes, the gametophyte (haploid) is the dominant, free-living generation (the green, photosynthetic plant body). The sporophyte (diploid) is dependent on the gametophyte."),
  mkQ(420,"Plant Anatomy","medium","Which conducting tissue transports organic solutes (sugars) from leaves to other parts?",["Xylem (vessels and tracheids)","Phloem (sieve tubes)","Collenchyma","Parenchyma"],1,"Phloem transports photosynthates (sucrose) from source (leaves) to sink (roots, fruits) by pressure flow (Munch's mass flow hypothesis). Xylem transports water and minerals upward."),
  mkQ(421,"Plant Physiology","medium","C₄ plants have an advantage over C₃ plants under hot, bright conditions because they:",["Use more water","Lack photorespiration due to CO₂ concentrating mechanism","Produce more O₂","Have smaller leaves"],1,"In C₄ plants, CO₂ is concentrated in bundle sheath cells where RuBisCO operates at near-saturating CO₂, suppressing oxygenase activity and photorespiration. This improves photosynthetic efficiency."),
  mkQ(422,"Plant Anatomy","medium","Collenchyma tissue provides mechanical support to which plant organs?",["Mature woody stems only","Young growing stems, petioles, and leaf margins","Root hairs","Seed endosperm"],1,"Collenchyma: living cells with unevenly thickened cell walls (cellulose + pectin at corners). Found in young stems, petioles — provides support while allowing growth (unlike sclerenchyma which is rigid/dead)."),
  mkQ(423,"Plant Physiology","medium","Guttation (secretion of liquid water droplets from leaf tips) occurs via:",["Stomata (during day)","Hydathodes (water pores at leaf margins)","Lenticels (in bark)","Root hairs"],1,"Guttation: root pressure pushes water through hydathodes (specialised pores at leaf margins/tips) during cool nights when transpiration is low. The fluid contains minerals."),
  mkQ(424,"Plant Physiology","medium","Photoperiodism refers to the plant's response to:",["Light intensity (lux)","Relative duration of light and dark periods per day","Quality (wavelength) of light","Direction of light (for phototropism)"],1,"Photoperiodism: flowering is triggered by critical day length. Long-day plants (LDP) flower when light > critical length (e.g., wheat). Short-day plants (SDP) flower when dark > critical length (e.g., chrysanthemum)."),
  mkQ(425,"Plant Anatomy","medium","INCORRECT about xylem:",["It transports water and dissolved minerals from roots to leaves","It is mostly dead tissue at maturity (vessels, tracheids)","It transports organic solutes (sugars) from leaves","It is lignified, providing structural support"],2,"Xylem transports water and minerals (not organic solutes). Phloem transports sugars. Xylem (wood) also provides mechanical support via lignified cell walls."),
  mkQ(426,"Plant Kingdom","medium","In the plant kingdom, which group first evolved TRUE SEEDS?",["Bryophytes","Pteridophytes","Gymnosperms (and continued in angiosperms)","Only angiosperms"],2,"Seeds (with seed coat, embryo, nutritive tissue) first evolved in gymnosperms. Seeds represent a major evolutionary advance: they protect the embryo and provide stored nutrients for germination."),
  mkQ(427,"Plant Physiology","medium","Which gas produced during anaerobic respiration in waterlogged soil is toxic to plants?",["CO₂","O₂","Ethylene","Ethanol and organic acids (e.g., lactic acid)"],3,"In waterlogged soils, anaerobic bacteria produce ethanol and organic acids, which are toxic to roots. This is why prolonged flooding kills most plants (except rice and other adapted species)."),
  mkQ(428,"Plant Anatomy","medium","Aerenchyma (air spaces in stem/roots) helps aquatic and wetland plants by:",["Increasing rigidity","Providing aeration to submerged tissues (buoyancy and O₂ supply)","Storing water","Protecting from herbivores"],1,"Aerenchyma: interconnected air spaces in cortex/stem allow diffusion of O₂ to roots submerged in anaerobic waterlogged soil. Also provides buoyancy in hydrophytes."),
  mkQ(429,"Plant Kingdom","medium","Which of the following is NOT true about Psilotum (whisk fern)?",["It lacks true roots","It is a primitive pteridophyte","It has seeds for reproduction","It has dichotomously branched stems"],2,"Psilotum is a primitive pteridophyte that lacks roots and leaves but has dichotomously branching stems with sporangia. It reproduces via SPORES (not seeds). Seeds evolved only in gymnosperms/angiosperms."),
  mkQ(430,"Plant Physiology","easy","The process by which ADP + Pi are combined to form ATP using light energy in chloroplasts is:",["Substrate-level phosphorylation","Oxidative phosphorylation","Photophosphorylation","Chemosynthesis"],2,"Photophosphorylation: ATP synthesis using light energy in thylakoid membranes (via photosystems and ATP synthase). Occurs in both cyclic (only PSI) and non-cyclic (PSI+PSII) forms."),
];

// ── TEST 5 ──
const T5 = [
  mkQ(501,"Ecology","easy","A food chain reads: Grass → Grasshopper → Frog → Snake → Eagle. The frog is a:",["Producer","Primary consumer","Secondary consumer","Tertiary consumer"],2,"Grass = producer. Grasshopper = 1° consumer. Frog = 2° consumer (eats grasshopper). Snake = 3° consumer. Eagle = 4° consumer (apex predator)."),
  mkQ(502,"Ecology","easy","The term 'ecosystem' was coined by:",["Ernst Haeckel (coined 'ecology')","Eugene Odum","Arthur Tansley (1935)","Charles Elton"],2,"Arthur Tansley (1935) coined 'ecosystem' to describe a natural unit consisting of biotic community + abiotic environment. Haeckel coined 'ecology' in 1866."),
  mkQ(503,"Ecology","easy","Which is the correct energy transfer efficiency per trophic level (Lindeman's 10% rule)?",["90% of energy is transferred","50% of energy is transferred","10% of energy is transferred (90% lost as heat)","1% is transferred"],2,"Only ~10% of energy at one trophic level is incorporated into the next. The rest (90%) is lost as heat (metabolic processes, respiration). This limits food chain length."),
  mkQ(504,"Ecology","easy","Which gas is primarily responsible for stratospheric ozone depletion?",["CO₂ (carbon dioxide)","SO₂ (sulphur dioxide)","CFC (chlorofluorocarbons)","NO₂ (nitrogen dioxide)"],2,"CFCs (from refrigerants, aerosols) release Cl atoms in stratosphere. Each Cl atom can destroy thousands of O₃ molecules: Cl + O₃ → ClO + O₂."),
  mkQ(505,"Ecology","medium","Which of the following is an IN SITU conservation method?",["Zoo","Botanical garden","Cryopreservation of seeds in gene bank","Biosphere reserve"],3,"In situ = protection in natural habitat: national parks, wildlife sanctuaries, biosphere reserves. Ex situ = outside natural habitat: zoos, botanical gardens, gene banks, seed banks."),
  mkQ(506,"Ecology","medium","The relationship where one organism benefits and the other is neither harmed nor helped is called:",["Mutualism","Parasitism","Commensalism","Competition"],2,"Commensalism: commensal benefits, host is unaffected. Examples: epiphytes (orchids on trees), remoras on sharks, barnacles on whale skin."),
  mkQ(507,"Ecology","medium","Eutrophication of water bodies (algal blooms, oxygen depletion) is caused by:",["Oil spills","Excess nutrients (nitrogen and phosphorus from fertilisers/sewage)","Heavy metal contamination","Acid rain"],1,"Eutrophication: excess N and P → massive algal growth → algal blooms → algae die and decompose (bacterial decomposition uses all O₂) → hypoxia kills fish. A major freshwater pollution problem."),
  mkQ(508,"Ecology","easy","The maximum population size an environment can sustainably support is called:",["Biotic potential","Carrying capacity (K)","Population density","Age distribution"],1,"Carrying capacity (K) = maximum population size sustainable given available resources. In logistic (S-curve) growth, population stabilises at K. Biotic potential = max growth rate under ideal conditions."),
  mkQ(509,"Ecology","medium","Acid rain is primarily caused by emissions of:",["CO₂ and CO","SO₂ and NOₓ (react with water to form H₂SO₄ and HNO₃)","CFCs","Methane (CH₄)"],1,"Acid rain: SO₂ (from burning coal/fuel) + NOₓ (from vehicle exhausts) dissolve in rainwater → H₂SO₄ and HNO₃ (pH < 5.6). Damages forests, corrodes buildings, acidifies water bodies."),
  mkQ(510,"Ecology","medium","The pyramid of numbers is INVERTED in which ecosystem?",["Grassland ecosystem","Aquatic pond ecosystem","Forest ecosystem (single tree supports many parasites)","Desert ecosystem"],2,"Forest ecosystem: one large tree (1 producer) → hundreds of insects → tens of birds → few top predators → inverted pyramid of numbers. But pyramid of energy is ALWAYS upright."),
  mkQ(511,"Ecology","medium","Which of the following is a DENSITY-INDEPENDENT factor limiting population growth?",["Intraspecific competition","Disease outbreaks","Predation","Earthquake / Flood"],3,"Density-independent factors affect population regardless of its size: temperature extremes, storms, earthquakes, floods. Density-dependent factors (competition, predation, disease) intensify as population increases."),
  mkQ(512,"Ecology","easy","Carbon moves from the atmosphere to living organisms primarily through:",["Respiration","Decomposition","Photosynthesis (CO₂ fixed by plants)","Combustion"],2,"Carbon cycle: atmospheric CO₂ → photosynthesis → organic carbon in plants → food chains → CO₂ released by respiration, decomposition, and combustion."),
  mkQ(513,"Ecology","medium","INCORRECT statement about biodiversity:",["India is one of 12 megadiversity countries","Tropical regions have higher biodiversity than polar regions","All species on Earth have been discovered and scientifically described","Genetic diversity helps species survive environmental changes"],2,"Only ~1.8 million species have been formally described. Estimated total = 8.7 million species (eukaryotes alone). Most species remain undiscovered, especially in tropical rainforests."),
  mkQ(514,"Ecology","medium","Ecological niche refers to:",["The physical location where an organism lives","The functional role of an organism in its ecosystem","The food an organism eats","The territory an organism defends"],1,"Niche = functional role of a species in its ecosystem (what it eats, when it is active, what it provides, relationships with other species). Two species cannot occupy the same niche in the same place (competitive exclusion)."),
  mkQ(515,"Ecology","medium","Primary productivity is best defined as:",["Energy used by primary consumers","Rate of biomass production by autotrophs (producers) per unit area per unit time","Total solar energy falling on ecosystem","Production by decomposers"],1,"Primary productivity = rate at which autotrophs fix solar energy into organic matter. GPP (Gross PP) = total fixed. NPP (Net PP) = GPP − plant respiration (available to consumers)."),
  mkQ(516,"Ecology","easy","DDT concentration INCREASING as it moves up the food chain is an example of:",["Eutrophication","Biological control","Biomagnification (bioaccumulation)","Bioremediation"],2,"Biomagnification: persistent lipid-soluble toxins (DDT, PCBs, Hg) accumulate in fat tissue and concentrate at each trophic level. Top predators have highest concentrations."),
  mkQ(517,"Ecology","medium","The relationship between clownfish and sea anemone (clownfish lives among anemone's stinging tentacles) is:",["Parasitism (anemone harmed)","Predation","Mutualism (both benefit)","Commensalism"],2,"Mutualism: Clownfish gains protection in anemone tentacles + food scraps. Anemone gains: clownfish removes parasites and lures prey. Both benefit."),
  mkQ(518,"Ecology","medium","Which of the following correctly represents the sequence in an ecological succession (from pioneer to climax)?",["Lichen → Moss → Grass → Shrubs → Trees","Trees → Shrubs → Grass → Moss → Lichen","Grass → Lichen → Moss → Shrubs → Trees","Soil → Lichen → Shrubs → Moss → Trees"],0,"Xerarch (primary) succession on bare rock: Crustose lichens → Foliose lichens → Mosses → Grasses → Shrubs → Climax forest. Pioneers (lichens) break down rock to form soil."),
  mkQ(519,"Ecology","medium","Ex situ conservation refers to protecting organisms:",["In their natural habitat","Outside their natural habitat (zoos, gene banks, botanical gardens)","Only in national parks","Only in sanctuaries"],1,"Ex situ = away from natural habitat: zoos, botanical gardens, seed banks, cryopreservation, tissue culture collections. Used when in situ protection is insufficient or impossible."),
  mkQ(520,"Ecology","easy","Food web differs from food chain in that:",["Food web is simpler and linear","A food web consists of multiple interconnected food chains","Food chain shows all trophic levels, food web does not","Energy does not flow in food webs"],1,"A food chain is a single, linear path of energy flow. A food web = network of interconnected food chains showing the complex feeding relationships in an ecosystem."),
  mkQ(521,"Ecology","medium","The depletion of stratospheric ozone leads to an increase in which type of radiation reaching Earth's surface?",["Infrared (IR) radiation","Visible light","UV-B radiation (280-315 nm)","Gamma radiation"],2,"Stratospheric ozone absorbs UV-B and UV-C radiation. Depletion → increased UV-B reaching Earth → skin cancer, cataracts, DNA damage in organisms, reduced photosynthesis."),
  mkQ(522,"Ecology","medium","In logistic growth (S-shaped/sigmoidal curve), the rate of population increase is MAXIMUM at:",["Population size = K (carrying capacity)","Very small population size","Population size = K/2","Population size > K"],2,"In logistic growth: dN/dt = rN(K-N)/K. Maximum growth rate occurs at N = K/2 (inflection point of sigmoid curve). At N=K, growth rate approaches 0."),
  mkQ(523,"Ecology","easy","Which of the following is used as a biofertilizer for rice cultivation to improve yield?",["Vibrio","Rhizobium","Azolla pinnata (with Anabaena)","Fusarium"],2,"Azolla pinnata (a floating fern) harbours Anabaena azollae (cyanobacterium) in its leaf cavities, which fixes atmospheric N₂. It is used as a green manure/biofertilizer in rice paddies."),
  mkQ(524,"Ecology","medium","Wetland ecosystems are important because they:",["Increase flooding downstream by blocking water flow","Serve as biodiversity hotspots, water filters, and carbon sinks","Reduce rainfall in surrounding areas","Have no commercial value"],1,"Wetlands: filter pollutants, recharge groundwater, control floods, store carbon (peat bogs), support unique biodiversity (migratory birds, amphibians, plants). Among most productive ecosystems."),
  mkQ(525,"Ecology","medium","A biological indicator of freshwater organic pollution (very low DO, high BOD) is the presence of:",["Trout and salmon","Mayfly larvae (Ephemeroptera)","Tubifex worms and rat-tailed maggots","Diatoms"],2,"Tubifex worms (oligochaete worms) and rat-tailed maggots tolerate very low oxygen — indicators of severe organic pollution (Class IV water quality). Trout need clean, well-oxygenated water."),
  mkQ(526,"Ecology","medium","The concept of biological control uses:",["Chemical pesticides to suppress pests","Natural enemies (predators, parasitoids, pathogens) to control pest populations","Genetic modification of crops","Crop rotation"],1,"Biological control: using natural enemies — predators (ladybird beetle eats aphids), parasitoids (Trichogramma wasps against crop pests), pathogens (Bacillus thuringiensis Bt toxin)."),
  mkQ(527,"Ecology","hard","The carbon stored in peat bogs and permafrost represents a threat to climate because:",["It reflects sunlight","It absorbs harmful UV","When thawed/decomposed, it releases large amounts of CO₂ and CH₄ (positive feedback loop)","It is harmless"],2,"Arctic permafrost and peat bogs store billions of tonnes of organic carbon. Climate warming → thawing → microbial decomposition → CO₂ and CH₄ release → more warming (positive feedback)."),
  mkQ(528,"Ecology","medium","The term 'ecological footprint' refers to:",["The tracks left by animals in soil","The area of productive land and sea required to support a person's lifestyle","The size of a species' territory","The rate of habitat loss"],1,"Erawith ecological footprint = measure of human demand on Earth's ecosystems — the area of biologically productive land/sea needed to produce resources consumed and absorb waste generated."),
  mkQ(529,"Ecology","medium","Taj Mahal (marble monument in Agra, India) is being corroded by:",["CO₂ from vehicle exhaust","Ozone from UV","SO₂ from Mathura refinery (forms H₂SO₄ — 'marble cancer')","HF from industries"],2,"SO₂ pollution from Mathura Petroleum Refinery reacts with rain → H₂SO₄ → reacts with CaCO₃ (marble) → CaSO₄ (gypsum) + CO₂ + H₂O. The marble turns yellow/black and crumbles."),
  mkQ(530,"Ecology","easy","Which of the following gas contributes MOST to the greenhouse effect (global warming)?",["CFC","Methane","Nitrous oxide","Carbon dioxide (CO₂) — largest contribution by volume"],3,"CO₂ contributes ~64% of enhanced greenhouse effect (most by mass emitted). But methane (CH₄) is ~25× more potent per molecule. CFCs are most potent per molecule but present in tiny amounts."),
];

// ── TEST 6 ──
const T6 = [
  mkQ(601,"Biotechnology","easy","Golden Rice was developed to address deficiency of which nutrient?",["Protein","Iron","Vitamin A (β-carotene)","Vitamin D"],2,"Golden Rice was genetically engineered to produce β-carotene (provitamin A) in the endosperm by inserting genes from daffodil and soil bacterium. It addresses Vitamin A deficiency blindness."),
  mkQ(602,"Biotechnology","easy","The Ti plasmid used to introduce foreign genes into plants is derived from:",["Escherichia coli","Bacillus thuringiensis","Agrobacterium tumefaciens","Rhizobium leguminosarum"],1,"Agrobacterium tumefaciens (soil bacterium causing crown gall disease) has the Ti (tumour-inducing) plasmid. A portion (T-DNA) integrates into plant nuclear genome, used to deliver foreign genes."),
  mkQ(603,"Biotechnology","easy","Bt toxin (Cry proteins) used in transgenic crops is produced by:",["Bacillus thermophilus","Brevibacillus laterosporus","Bacillus thuringiensis","Borrelia burgdorferi"],2,"Bacillus thuringiensis (Bt) produces Cry (crystal) proteins that are toxic to specific insect larvae (bollworm, corn borer). The toxin is activated in alkaline insect gut, forms pores, killing the larva."),
  mkQ(604,"Biotechnology","medium","In recombinant DNA technology, vectors (like plasmids) serve as:",["Enzymes that cut DNA","Molecules that transport and replicate foreign DNA in host cells","Selectable markers only","Promoters for transcription"],1,"Vectors: DNA molecules that carry foreign DNA into host cells for replication (cloning). They must have: origin of replication, selectable marker, multiple cloning site (MCS)."),
  mkQ(605,"Biotechnology","easy","The first human protein produced commercially by recombinant DNA technology (1982) was:",["Human growth hormone","Tissue plasminogen activator","Insulin (Humulin by Eli Lilly)","Erythropoietin"],2,"Recombinant human insulin (Humulin): insulin A and B chain genes inserted separately into E. coli; chains produced, extracted, and combined to form active insulin. Replaced pig/cow insulin."),
  mkQ(606,"Biotechnology","easy","PCR (Polymerase Chain Reaction) is used to:",["Separate DNA by size","Sequence DNA","Amplify specific DNA sequences exponentially","Express foreign genes in bacteria"],2,"PCR (Kary Mullis, 1983): exponential amplification of specific DNA using primers and heat-stable Taq polymerase. 3 steps: denaturation (94°C) → annealing (50-65°C) → extension (72°C)."),
  mkQ(607,"Biotechnology","medium","Southern blotting is used to detect:",["Specific RNA sequences","Specific protein (antigen) sequences","Specific DNA sequences using labelled probes","Chromosomal number"],2,"Southern blot (E.M. Southern, 1975): DNA fragments separated by gel electrophoresis → transferred to membrane → hybridised with labelled probe → detects specific DNA sequences (gene presence/absence)."),
  mkQ(608,"Immunity","easy","Which type of white blood cell (WBC) is responsible for producing antibodies?",["Neutrophil","Basophil","Cytotoxic T cell","B lymphocyte (plasma cells)"],3,"B lymphocytes, when activated (by T helper cells + antigen), differentiate into plasma cells that mass-produce antibodies (immunoglobulins). Memory B cells persist for long-term immunity."),
  mkQ(609,"Immunity","medium","Passive immunity is acquired by:",["Vaccination (active immunisation)","Natural infection","Transfer of pre-formed antibodies (serum therapy, maternal antibodies)","Memory T cell activation"],2,"Passive immunity: ready-made antibodies transferred. Examples: maternal IgG crosses placenta (natural), maternal IgA in breast milk, antivenom/antitoxin serum (artificial). Quick but temporary — no memory."),
  mkQ(610,"Immunity","easy","ELISA (Enzyme-Linked Immunosorbent Assay) is widely used for:",["Amplifying DNA sequences","Detecting antigens or antibodies (e.g., HIV diagnosis)","Separating proteins by size","Chromosomal analysis"],1,"ELISA: antibody linked to enzyme detects antigen (or vice versa). Enzyme converts substrate to coloured product. Used for HIV diagnosis, pregnancy tests (HCG), food allergen detection."),
  mkQ(611,"Immunity","medium","Autoimmune diseases occur when:",["Immune system is suppressed by stress","Immune system attacks self-antigens (loss of tolerance)","Too many pathogens overwhelm immunity","Vaccine causes disease"],1,"Autoimmunity: T and B cells target self-antigens. Examples: rheumatoid arthritis (joints), Type 1 diabetes (β cells), SLE (lupus), multiple sclerosis (myelin), Hashimoto's thyroiditis."),
  mkQ(612,"Immunity","medium","The primary immune response (on first exposure to antigen) differs from secondary response in that it:",["Is faster and produces more IgG","Is slower, produces mainly IgM initially, and of lower magnitude","Activates cytotoxic T cells only","Produces no memory cells"],1,"Primary response: 1-2 weeks lag, mainly IgM, lower titres. Secondary response (re-exposure): faster (2-3 days), higher IgG titres, longer lasting — due to memory B and T cells."),
  mkQ(613,"Immunity","easy","HIV (Human Immunodeficiency Virus) primarily infects and destroys:",["Neutrophils","B lymphocytes","CD4+ T helper lymphocytes","Red blood cells"],2,"HIV specifically binds to CD4 receptor on T helper cells (and macrophages/dendritic cells). As CD4+ count falls below 200/µL, susceptibility to opportunistic infections defines AIDS."),
  mkQ(614,"Biotechnology","medium","CRISPR-Cas9 gene editing works by:",["Inserting a random mutation into the genome","Using guide RNA to direct Cas9 endonuclease to cut specific DNA sequences","Amplifying DNA without a template","Removing mRNA from cells"],1,"CRISPR-Cas9: guide RNA (gRNA) complementary to target DNA guides Cas9 (nuclease) to create a precise double-strand break. The cell's repair (NHEJ or HDR) can create mutations or insert sequences."),
  mkQ(615,"Biotechnology","medium","Which technique allows the identification of specific genes expressed in a cell/tissue by analysing mRNA?",["Southern blotting (DNA)","Western blotting (protein)","Northern blotting (RNA) or microarray","ELISA"],2,"Northern blotting: detects specific RNA sequences (like Southern but for RNA). DNA microarray: simultaneously analyses expression of thousands of genes (global transcriptome profiling)."),
  mkQ(616,"Immunity","medium","Interferons are proteins secreted by virus-infected cells that:",["Kill viruses directly","Signal adjacent cells to produce antiviral proteins (non-specific defence)","Produce antibodies","Activate complement directly"],1,"Interferons (IFN-α, IFN-β, IFN-γ): glycoproteins secreted by infected cells. They 'interfere' with viral replication in neighboring cells by inducing antiviral state (upregulate MHC, activate NK cells)."),
  mkQ(617,"Biotechnology","medium","Somatic cell gene therapy differs from germline gene therapy in that:",["It is more expensive","Changes are heritable in somatic therapy","Changes are NOT heritable (only in individual's somatic cells, not in germ cells)","It uses different vectors"],2,"Somatic gene therapy: corrects genetic defect in body (non-reproductive) cells of individual — not inherited by offspring. Germline gene therapy: changes in egg/sperm → heritable (ethically controversial)."),
  mkQ(618,"Immunity","easy","Which immunoglobulin (antibody class) is the MOST ABUNDANT in human blood serum?",["IgM (first in primary response)","IgE (allergy/parasites)","IgG (most abundant, crosses placenta)","IgA (mucosal secretions)"],2,"IgG: ~75-80% of serum immunoglobulins. It is the most important in secondary immune response, the ONLY one that crosses the placenta (passive neonatal immunity), and activates complement."),
  mkQ(619,"Biotechnology","medium","Transgenic animals are used in biomedical research to:",["Produce cheaper food","Study gene function in a living organism, model human diseases, produce pharmaceutical proteins","Replace lab chemicals","Avoid need for animal ethics approval"],1,"Transgenic animals (e.g., knockout mice): human disease models (cancer, Alzheimer's, CF), production of pharmaceutical proteins (e.g., transgenic goats producing antithrombin in milk), vaccine testing."),
  mkQ(620,"Immunity","medium","The classical complement pathway is activated by:",["Mannose on microbial surfaces","Spontaneous hydrolysis of C3","Antigen-antibody (IgG/IgM) complexes","All the above (convergent)"],2,"Classical pathway: initiated by C1q binding to Fc region of IgG/IgM in antigen-antibody complexes → complement cascade → membrane attack complex (MAC) → cell lysis."),
  mkQ(621,"Biotechnology","easy","Which vector has the LARGEST cloning capacity?",["Plasmid (~10 kb)","Cosmid (~40 kb)","BAC - Bacterial Artificial Chromosome (~150 kb)","YAC - Yeast Artificial Chromosome (up to 2000 kb)"],3,"Cloning capacity: Plasmid < Cosmid < BAC < YAC. YAC can carry up to 2 Mb of foreign DNA — essential for the Human Genome Project (HGP) for cloning large chromosomal regions."),
  mkQ(622,"Immunity","medium","INCORRECT about vaccines:",["They use attenuated (weakened) or killed pathogens","They prevent infection by providing immunological memory","They provide immediate protection within hours of administration","Toxoid vaccines use inactivated bacterial toxins"],2,"Vaccines take 1-2 weeks to provide protection (time needed to mount primary immune response and create memory cells). They do NOT provide immediate protection (unlike antivenom/antitoxin serum therapy)."),
  mkQ(623,"Biotechnology","medium","Bioremediation involves:",["Enhancing crop yields using fertilisers","Using microorganisms to degrade environmental pollutants (oil spills, heavy metals)","Gene therapy for genetic diseases","Producing biofuels from algae only"],1,"Bioremediation: using bacteria, fungi, or plants (phytoremediation) to clean up pollution. E.g., Pseudomonas putida degrades crude oil; Bacillus for heavy metals; Phanerochaete for lignin/DDT."),
  mkQ(624,"Immunity","hard","MHC (Major Histocompatibility Complex) molecules are important in immunity because they:",["Kill pathogens directly","Present peptide antigens to T lymphocytes (T cell activation)","Produce antibodies","Activate the complement system"],1,"MHC molecules (HLA in humans): MHC I (on all nucleated cells) presents intracellular peptides to CD8+ T cells. MHC II (on APCs) presents extracellular peptides to CD4+ T helper cells."),
  mkQ(625,"Biotechnology","medium","The technique of producing identical copies of an organism using a donor nucleus is called:",["In vitro fertilisation","Somatic cell nuclear transfer (SCNT) / Reproductive cloning","Transgenesis","Mutagenesis"],1,"SCNT (reproductive cloning): nucleus from somatic cell → enucleated egg cell → embryo → clone. Dolly the sheep (1996, Roslin Institute) was the first mammal cloned this way."),
  mkQ(626,"Immunity","medium","Natural killer (NK) cells differ from cytotoxic T cells (CTL) in that NK cells:",["Require antigen presentation via MHC I to activate","Are part of innate immunity and kill without prior sensitisation","Only kill cancer cells","Are activated only by interleukins"],1,"NK cells (innate immunity): recognise cells lacking MHC I (stressed, virally infected, or tumour cells) and kill them via perforin/granzyme without needing prior sensitisation or MHC restriction."),
  mkQ(627,"Biotechnology","medium","RNA interference (RNAi) involves:",["Inserting foreign RNA into the genome","Short dsRNA (siRNA) triggering sequence-specific degradation of mRNA","Reverse transcription of mRNA","Amplification of RNA"],1,"RNAi: double-stranded RNA (dsRNA) is processed by Dicer into siRNA → loaded into RISC → guides sequence-specific cleavage of target mRNA → gene silencing. Used in research and therapeutics."),
  mkQ(628,"Immunity","easy","Bone marrow is the site of origin for which immune cells (and maturation for B cells)?",["T cells (mature in thymus)","B cells (origin AND mature here)","NK cells and B cells originate here","All immune cells originate here, but mature elsewhere"],2,"All blood cells, including B cells, NK cells, and T cell precursors, originate in bone marrow. B cells mature in bone marrow. T cell precursors migrate to thymus for maturation. NK cells mature in bone marrow."),
  mkQ(629,"Biotechnology","hard","In the 'pharming' application of transgenics, human pharmaceutical proteins are produced in:",["Bacteria only","Transgenic livestock (e.g., milk) or plants","Recombinant yeast only","Tissue culture cells only"],1,"Pharming: pharmaceutical + farming. Transgenic goats/cows/sheep produce human proteins (e.g., antithrombin, alpha-1-antitrypsin, human lactoferrin) in their milk. Plants also used (e.g., tobacco for hepatitis B VLPs)."),
  mkQ(630,"Immunity","medium","The BCG vaccine (Bacillus Calmette-Guérin) provides protection against:",["Malaria","Cholera","Tuberculosis (TB)","Typhoid"],2,"BCG vaccine: live attenuated strain of Mycobacterium bovis. Provides protection against severe forms of TB (especially TB meningitis and miliary TB in children). Routine vaccination in India."),
];

// ── TEST 7 ──
const T7 = [
  mkQ(701,"Evolution","medium","Lamarck's theory of evolution proposed that:",["Natural selection drives evolution","Populations evolve through survival of the fittest","Acquired characteristics (traits developed during an organism's lifetime) are inherited","Mutations are the source of variation"],2,"Lamarckism: use and disuse of organs; acquired characters are inherited (e.g., giraffe stretched neck → longer neck passed to offspring). Disproved by Weismann — germline is separate from soma."),
  mkQ(702,"Evolution","medium","The Miller-Urey experiment (1953) demonstrated that:",["Life evolved from RNA","Amino acids (organic molecules) can form abiotically under early Earth conditions","DNA is the genetic material","Evolution is driven by mutation"],1,"Miller-Urey: recreated early Earth atmosphere (H₂, CH₄, NH₃, H₂O) + electrical sparks (lightning) → produced amino acids, sugars, and other organic molecules. Supported chemical evolution theory."),
  mkQ(703,"Evolution","medium","Hardy-Weinberg equilibrium states that allele and genotype frequencies in a population remain constant if:",["Population is small","Mutations occur at high rates","Random mating occurs in a large population with no selection, mutation, migration, or genetic drift","Natural selection is strong"],2,"Hardy-Weinberg law: p² + 2pq + q² = 1 (genotype freq). Allele frequencies constant if: large population, random mating, no mutation, no selection, no migration, no genetic drift."),
  mkQ(704,"Evolution","easy","Vestigial organs in humans (e.g., coccyx, wisdom teeth, appendix) provide evidence for evolution because they:",["Perform important functions","Were functional in ancestors but reduced in descendants — showing common ancestry","Appeared suddenly by mutation","Are adaptations to current environment"],1,"Vestigial organs: remnants of structures that were functional in ancestors. Coccyx = remnant of tail (primate ancestor), appendix = caecum remnant (herbivore ancestor), goosebumps = piloerection (for insulation in furry ancestors)."),
  mkQ(705,"Evolution","medium","Analogous organs (like wings of insects and wings of birds) indicate:",["Divergent evolution from a common ancestor","Convergent evolution — unrelated organisms evolving similar structures due to similar selective pressures","Parallel evolution in closely related species","Horizontal gene transfer"],1,"Convergent evolution: unrelated organisms independently evolve similar features (analogous organs) in response to similar environmental challenges. Wings of butterflies, bats, and birds all enable flight but evolved independently."),
  mkQ(706,"Evolution","medium","Which scientist independently proposed Natural Selection around the same time as Darwin?",["Thomas Huxley","Jean-Baptiste Lamarck","Alfred Russel Wallace","Ernst Haeckel"],2,"Alfred Russel Wallace (1858): independently developed Natural Selection theory. His letter to Darwin prompted Darwin to rush publication of 'On the Origin of Species' (1859). Both presented jointly to Linnean Society."),
  mkQ(707,"Evolution","hard","The 'RNA world' hypothesis proposes that early life used RNA as both:",["The structural molecule and energy source","Genetic information storage AND catalysis (ribozymes) before DNA and protein","Signalling molecule and transport molecule","Enzyme and membrane component"],1,"RNA World (Walter Gilbert, 1986): RNA was the first informational polymer. It can store genetic information (like DNA) AND catalyse reactions (ribozymes). Later, DNA replaced RNA for storage, proteins for catalysis."),
  mkQ(708,"Evolution","medium","Genetic drift is most significant in which type of population?",["Very large, diverse populations","Isolated small populations (bottleneck or founder effect)","Populations under strong selection","Cosmopolitan (widespread) species"],1,"Genetic drift = random changes in allele frequencies. Effect is GREATEST in small populations where chance events significantly alter allele frequencies. Bottleneck effect (population crash) and founder effect are examples."),
  mkQ(709,"Evolution","easy","Darwin's finches in the Galápagos Islands are cited as evidence for which phenomenon?",["Convergent evolution","Artificial selection","Adaptive radiation from a common ancestor","Genetic drift only"],2,"Adaptive radiation: single ancestor colonised Galápagos → diversified into ~14 species with different beak shapes adapted to different food sources (seeds, insects, cactus nectar). Classic example of evolution in action."),
  mkQ(710,"Evolution","medium","The concept of 'punctuated equilibrium' (Eldredge and Gould, 1972) proposes that evolution:",["Is always gradual (phyletic gradualism)","Proceeds at a constant rate","Occurs in rapid bursts (speciation events) separated by long periods of stasis","Is primarily driven by sexual selection"],2,"Punctuated equilibrium: fossil record shows long stable periods (stasis) with rapid morphological change during speciation. Contrasts with Darwin's gradualism. Both patterns are seen in the fossil record."),
  mkQ(711,"Classification","easy","The binomial nomenclature system of naming organisms was introduced by:",["Charles Darwin","Gregor Mendel","Carl Linnaeus (1758, 'Systema Naturae')","Ernst Mayr"],2,"Carolus Linnaeus standardised binomial nomenclature: Genus + species (both latinised). Scientific names allow unambiguous communication globally regardless of local common names."),
  mkQ(712,"Evolution","medium","Natural selection acts DIRECTLY on:",["Genotype (DNA sequence)","Phenotype (observable characteristics)","mRNA sequences","Recessive alleles only"],1,"Natural selection acts on phenotype (what is visible and functional). Organisms with phenotypes better suited to the environment reproduce more successfully. Underlying genotype is indirectly selected."),
  mkQ(713,"Evolution","medium","Allopatric speciation differs from sympatric speciation in that allopatric requires:",["Polyploidy","Reproductive isolation without geographical separation","Geographical isolation (physical barrier preventing gene flow)","Habitat preference differences only"],2,"Allopatric: geographic barrier (mountain, river, ocean) separates populations → independent evolution → reproductive isolation → new species. Sympatric: same location, isolation by habitat preference, polyploidy, etc."),
  mkQ(714,"Evolution","medium","In evolutionary terms, Darwinian fitness refers to:",["Physical strength and size","Speed and agility","An organism's ability to reproduce successfully and pass on genes","Intelligence quotient"],2,"Fitness = reproductive success. The 'fittest' organism passes the most copies of genes to the next generation. A small, slow organism that reproduces prolifically is more fit than a large, strong, sterile one."),
  mkQ(715,"Classification","medium","Which taxonomic rank is BETWEEN class and family?",["Phylum","Order","Genus","Species"],1,"Taxonomic hierarchy (KPCOFGS): Kingdom → Phylum → Class → ORDER → Family → Genus → Species. Order is between Class and Family."),
  mkQ(716,"Evolution","medium","INCORRECT statement about evolution:",["Mutations provide the raw material for evolution","Natural selection acts on phenotypic variation","Evolution always leads to greater complexity","Genetic drift can cause evolution without natural selection"],2,"Evolution does NOT always lead to complexity. Organisms can evolve simplicity: parasites often evolve reduced body systems (e.g., tapeworms lost digestive system). Evolution = change in allele frequency, not necessarily progress toward complexity."),
  mkQ(717,"Evolution","medium","Industrial melanism in peppered moths (Biston betularia) in England is an example of:",["Genetic drift","Founder effect","Directional natural selection","Sexual selection"],2,"Industrial melanism: before industrialisation, light moths were camouflaged on lichen-covered bark. After coal pollution, dark bark → dark (melanic) moths were selected. Classic directional selection example."),
  mkQ(718,"Evolution","medium","Which epoch is associated with the emergence of modern Homo sapiens (~200,000 years ago)?",["Eocene","Oligocene","Miocene","Pleistocene"],3,"Homo sapiens evolved in the Pleistocene epoch (~2.6 million – 11,700 years ago). Modern humans emerged in Africa ~200,000 years ago. Out-of-Africa migration ~60,000-70,000 years ago."),
  mkQ(719,"Evolution","hard","Coevolution (two or more species evolving in response to each other) is best illustrated by:",["Antibiotic resistance in bacteria","Flowers and their specific pollinators (e.g., fig and fig wasp)","Migration of birds","Geographic isolation of island species"],1,"Coevolution: co-dependent species evolve together. Fig tree and fig wasp: obligate mutualism — each ficus species has ONE specific fig wasp species that pollinates it. Milkweed toxins and Monarch butterfly detoxification."),
  mkQ(720,"Classification","medium","Cladistics classifies organisms based on:",["Overall physical similarity (phenetics)","Shared derived characteristics (synapomorphies) — traits unique to a clade","Ecological role","Geographic location"],1,"Cladistics: organisms grouped by shared derived characters (evolved in common ancestor). Cladogram = branching diagram showing evolutionary relationships. Based on parsimony principle."),
  mkQ(721,"Evolution","medium","The 'molecular clock' hypothesis (Zuckerkandl & Pauling) states that:",["Evolution always happens at the same rate","Neutral mutations accumulate at a roughly constant rate, allowing divergence time estimation","DNA mutates faster in larger organisms","All genes evolve at the same rate"],1,"Molecular clock: neutral (non-functional) DNA mutations accumulate at relatively constant rates. By comparing molecular differences between species and calibrating with fossil dates, divergence times can be estimated."),
  mkQ(722,"Evolution","medium","Disruptive selection leads to:",["Narrowing of phenotypic range (stabilising selection)","Shift of population towards one extreme (directional)","Splitting of population into two extreme phenotypes (bimodal distribution)","No change in allele frequencies"],2,"Disruptive selection: both extremes are favoured, intermediate phenotypes selected against. Example: black and white Sooty tern in heterogeneous environments. Can lead to sympatric speciation."),
  mkQ(723,"Evolution","medium","Homologous organs (like forelimbs of human, bat, whale, and horse) indicate:",["Analogous function","Convergent evolution","Common ancestry (divergent evolution) — same basic structure, different functions","Random similarity"],2,"Homologous structures: same basic anatomical structure derived from same ancestor but modified for different functions. All tetrapod forelimbs have: humerus, radius, ulna, carpals, metacarpals, phalanges."),
  mkQ(724,"Classification","medium","Species is the lowest naturally occurring taxonomic unit. Two organisms belong to the same species if they:",["Look identical","Live in the same habitat","Can interbreed and produce FERTILE offspring","Have the same ecological niche"],2,"Biological species concept (Ernst Mayr): species = group of actually or potentially interbreeding natural populations, reproductively isolated from other groups. Key: fertile offspring (mule = horse × donkey is sterile → different species)."),
  mkQ(725,"Evolution","hard","'Neutral theory of molecular evolution' proposed by Motoo Kimura (1968) states that:",["All mutations are harmful","Most molecular evolution is driven by natural selection","Most molecular evolutionary change is due to random fixation of neutral (selectively equivalent) mutations","Genetic drift only affects small populations"],2,"Kimura's neutral theory: most DNA and protein sequence changes are neutral (neither beneficial nor harmful) and spread through populations by random genetic drift. Selection acts on a small fraction of mutations."),
  mkQ(726,"Evolution","medium","Biogeography (study of species distribution) provides evidence for evolution because:",["Species are evenly distributed globally","Species are most diverse in Arctic regions","Island species closely resemble mainland species (recent common ancestor) and have diversified from them","Marine species are unrelated to terrestrial species"],2,"Biogeography: species on islands resemble species on nearby mainland (colonised from mainland, then evolved separately). Darwin's finches (South American finch ancestor colonised Galápagos → diversified)."),
  mkQ(727,"Classification","easy","In the five-kingdom classification, organisms in Kingdom Protista are:",["Prokaryotic unicellular organisms","Multicellular eukaryotes","Unicellular or simple multicellular eukaryotes","Heterotrophic eukaryotes only"],2,"Kingdom Protista: all unicellular eukaryotes (Amoeba, Paramecium, Euglena, diatoms) and some simple multicellular algae (seaweeds). They don't fit into Fungi, Plantae, or Animalia."),
  mkQ(728,"Evolution","medium","The study of fossils (palaeontology) provides evidence for evolution by showing:",["That species were created separately","A record of organisms that lived in the past, demonstrating gradual changes in life forms over time","That evolution is always linear","That all current species have direct fossil ancestors"],1,"Fossil record: shows sequential appearance of increasingly complex organisms from simple to complex. Transitional fossils (e.g., Archaeopteryx = dinosaur-bird transition) show evolutionary links between groups."),
  mkQ(729,"Evolution","medium","Which of the following represents the correct chronological order of evolution of major groups?",["Vertebrates → Invertebrates → Plants → Prokaryotes","Prokaryotes → Eukaryotes → Multicellular organisms → Plants and Animals","Fungi → Plants → Animals → Bacteria","Humans → Primates → Mammals → Reptiles"],1,"Life timeline: Prokaryotes (3.8 bya) → Eukaryotes (1.8 bya) → Multicellular organisms (600 mya) → Cambrian explosion: invertebrates (530 mya) → Fish (500 mya) → Land plants (470 mya) → Mammals (225 mya) → Humans (~6 mya)."),
  mkQ(730,"Evolution","medium","Selective breeding (artificial selection) of crops and animals by humans demonstrates:",["That evolution cannot occur in short time frames","That directed selection CAN rapidly change the characteristics of a population","That all variation is environmentally caused","That Lamarck was correct"],1,"Artificial selection: dog breeds from wolf in ~15,000 years, maize from wild teosinte in ~9,000 years — dramatic phenotypic changes rapidly. Darwin used this analogy to explain natural selection."),
];

// ── TEST 8 ──
const T8 = [
  mkQ(801,"Neurology","medium","The myelin sheath around axons in the PERIPHERAL nervous system (PNS) is formed by:",["Astrocytes","Oligodendrocytes (in CNS)","Schwann cells","Microglia"],2,"Schwann cells wrap around axons in PNS to form myelin sheath. One Schwann cell = one segment. In CNS, oligodendrocytes form myelin; one oligodendrocyte can myelinate multiple axons."),
  mkQ(802,"Neurology","medium","The correct components and sequence of a reflex arc are:",["Receptor → Effector","Receptor → Sensory neuron → Interneuron → Motor neuron → Effector","Effector → Motor neuron → CNS → Sensory neuron → Receptor","Brain → Spinal cord → Muscles directly"],1,"Reflex arc: stimulus → receptor → afferent (sensory) neuron → spinal cord interneuron → efferent (motor) neuron → effector (muscle/gland). Bypasses the brain for speed."),
  mkQ(803,"Endocrinology","easy","Which gland is called the 'master gland' because it regulates most other endocrine glands?",["Thyroid gland","Adrenal gland","Pituitary gland (hypophysis)","Hypothalamus (controls pituitary)"],2,"Anterior pituitary (adenohypophysis) secretes: TSH, ACTH, FSH, LH, GH, Prolactin. It is called 'master gland.' BUT the hypothalamus controls the pituitary via releasing/inhibiting hormones."),
  mkQ(804,"Endocrinology","medium","Parathyroid hormone (PTH) primarily functions to:",["Lower blood glucose","Increase blood calcium (Ca²⁺) levels by stimulating bone resorption, kidney reabsorption, and vitamin D activation","Regulate metabolic rate","Promote sodium retention"],1,"PTH: released by parathyroid glands when Ca²⁺ is low → ↑ osteoclast activity (bone resorption), ↑ renal Ca²⁺ reabsorption, ↑ intestinal Ca²⁺ absorption (via vitamin D activation)."),
  mkQ(805,"Neurology","medium","The hypothalamus regulates all of the following EXCEPT:",["Body temperature (thermoregulation)","Hunger, thirst, and sleep-wake cycles","Anterior pituitary hormone secretion","Higher cognitive functions (reasoning, language)"],3,"Higher cognitive functions (language, planning, abstract thought) are functions of the cerebral cortex (frontal lobe). Hypothalamus = homeostasis: temperature, hunger, thirst, circadian rhythms, pituitary control."),
  mkQ(806,"Endocrinology","easy","Insulin is produced by which cells of the pancreatic islets of Langerhans?",["Alpha (α) cells — produce glucagon","Beta (β) cells — produce insulin","Delta (δ) cells — produce somatostatin","Acinar cells — produce digestive enzymes"],1,"β cells: insulin (decreases blood glucose by promoting uptake/storage). α cells: glucagon (increases blood glucose). δ cells: somatostatin (inhibits both insulin and glucagon)."),
  mkQ(807,"Neurology","easy","The corpus callosum is a band of nerve fibres that connects:",["Left and right cerebral hemispheres","Cerebrum and cerebellum","Brainstem and spinal cord","Thalamus and hypothalamus"],0,"Corpus callosum = largest white matter commissure; ~200 million axons connecting the two cerebral hemispheres, allowing communication and coordination between left and right brain."),
  mkQ(808,"Endocrinology","medium","ADH (Anti-Diuretic Hormone / Vasopressin) acts on which part of the kidney?",["Glomerulus","Proximal convoluted tubule","Collecting duct and distal convoluted tubule","Loop of Henle (ascending limb)"],2,"ADH (from posterior pituitary) acts on collecting duct and distal tubule: inserts aquaporin water channels → ↑ water reabsorption → concentrated urine. Deficiency → diabetes insipidus (dilute, large volume urine)."),
  mkQ(809,"Neurology","medium","The 'fight-or-flight' response (increased heart rate, dilated pupils, reduced digestion) is controlled by:",["Parasympathetic nervous system","Somatic nervous system","Sympathetic nervous system","Enteric nervous system"],2,"Sympathetic NS (fight-or-flight): noradrenaline release → ↑ heart rate, ↑ blood glucose, dilate pupils, bronchodilation, vasoconstriction of skin/gut, vasodilation of muscles. Parasympathetic = rest-and-digest."),
  mkQ(810,"Reproduction","easy","Implantation of the blastocyst occurs in the:",["Fallopian tube","Ovary","Endometrium (inner lining of the uterus)","Cervix"],2,"Implantation: blastocyst embeds in the endometrium ~6-10 days after fertilization. The endometrium thickens under progesterone (from corpus luteum) to prepare for implantation."),
  mkQ(811,"Endocrinology","medium","Which hormone surge triggers ovulation in the mid-menstrual cycle (~day 14)?",["FSH surge","Estrogen negative feedback","LH (Luteinizing Hormone) surge","Progesterone peak"],2,"LH surge: high estrogen from dominant follicle triggers a positive feedback LH surge from anterior pituitary → ovulation (follicle ruptures, releasing movie egg) ~36 hours later."),
  mkQ(812,"Reproduction","medium","The acrosome reaction in sperm occurs when sperm:",["Enters the fallopian tube","Binds to the zona pellucida of the egg (releasing hydrolytic enzymes to penetrate)","Undergoes capacitation in the female tract","Reaches the cervix"],1,"Acrosome reaction: sperm contacts zona pellucida → exocytosis of acrosomal enzymes (acrosin, hyaluronidase) → digests zona pellucida → sperm reaches egg plasma membrane."),
  mkQ(813,"Neurology","medium","Which structure integrates and relays sensory information to the appropriate cerebral cortex area?",["Hypothalamus","Cerebellum","Thalamus","Medulla oblongata"],2,"Thalamus = sensory relay station: all sensory signals (except olfaction) pass through thalamus before reaching cerebral cortex. Also involved in sleep/wakefulness and pain perception."),
  mkQ(814,"Endocrinology","easy","Glucagon is released by the pancreas when blood glucose is:",["High (after a meal)","Normal (fasting)","Low (hypoglycaemia)","Constantly (always)"],2,"Glucagon (from α cells): released during fasting/low glucose → stimulates glycogenolysis (breakdown of glycogen) and gluconeogenesis in liver → ↑ blood glucose (antagonistic to insulin)."),
  mkQ(815,"Reproduction","medium","Cleavage (the rapid mitotic divisions after fertilisation) is unusual because:",["DNA content increases dramatically","Cells get progressively SMALLER with each division (no growth phase)","Produces haploid cells","Requires meristem activity"],1,"Cleavage: rapid cell divisions with very short/absent G1 and G2 phases — cells divide before growing → blastomeres become progressively smaller. Overall embryo size doesn't increase until gastrulation."),
  mkQ(816,"Neurology","medium","Saltatory conduction (faster nerve impulse conduction) occurs along myelinated fibres because the impulse:",["Travels slowly through the myelin","Jumps from one node of Ranvier to the next (myelin is insulating)","Requires more energy than in unmyelinated fibres","Travels through myelin directly"],1,"Saltatory conduction: action potential 'jumps' between nodes of Ranvier (unmyelinated gaps in myelin) rather than propagating along entire axon membrane → much faster conduction velocity."),
  mkQ(817,"Endocrinology","medium","Cortisol (glucocorticoid from adrenal cortex) is primarily released in response to:",["High blood glucose","Low blood calcium","Stress (ACTH stimulation)","Dehydration"],2,"Cortisol: released in response to stress (via HPA axis: hypothalamus CRH → pituitary ACTH → adrenal cortex cortisol). Functions: ↑ blood glucose (gluconeogenesis), anti-inflammatory, immunosuppressive, ↑ fat mobilisation."),
  mkQ(818,"Reproduction","medium","Identical (monozygotic) twins form when:",["Two separate eggs are fertilised by two different sperm","One egg is fertilised by two sperm","A single zygote splits into two (or more) embryos","Two eggs are released and fertilised by the same sperm"],2,"Monozygotic twins: one fertilised egg (zygote) splits at 2-cell or early blastocyst stage → two genetically identical embryos. Share same DNA, different fingerprints (environmentally influenced)."),
  mkQ(819,"Endocrinology","medium","Which hormone promotes the development of secondary sexual characteristics in males?",["LH (triggers testosterone production)","FSH (sperm production)","Testosterone (the primary androgen)","Prolactin"],2,"Testosterone (from testicular Leydig cells, stimulated by LH): responsible for voice deepening, muscle mass increase, body hair, beard growth, spermatogenesis (with FSH), libido."),
  mkQ(820,"Neurology","medium","Parkinson's disease is caused by loss of dopamine-producing neurons in the:",["Cerebellum","Hippocampus","Substantia nigra (in basal ganglia)","Frontal cortex"],2,"Parkinson's: degeneration of dopaminergic neurons in substantia nigra (part of basal ganglia) → reduced dopamine in striatum → resting tremor, rigidity, bradykinesia, postural instability."),
  mkQ(821,"Reproduction","easy","During cleavage, the embryo passes through which stages in order?",["Blastula → Morula → Gastrula","Zygote → Morula → Blastula → Gastrula","Gastrula → Blastula → Morula","Morula → Zygote → Gastrula"],1,"Development sequence: Zygote → Cleavage → Morula (solid ball) → Blastula/Blastocyst (hollow sphere) → Gastrula (3 germ layers form). Tissue differentiation begins at gastrula stage."),
  mkQ(822,"Endocrinology","medium","Oxytocin is released from the posterior pituitary during labour and:",["Inhibits uterine contractions","Stimulates uterine contractions and milk let-down (ejection reflex)","Promotes ovulation","Maintains pregnancy"],1,"Oxytocin: positive feedback during labour (baby's head stimulates stretch → more oxytocin → stronger contractions). Also triggers milk ejection (suckling → hypothalamus → posterior pituitary → oxytocin → myoepithelial cells)."),
  mkQ(823,"Neurology","medium","Which neurotransmitter, when deficient at synapses, is associated with clinical depression?",["Dopamine (Parkinson's, reward)","GABA (inhibitory; anti-anxiety)","Serotonin (5-HT) — treated with SSRIs","Acetylcholine (Alzheimer's, muscle)"],2,"Serotonin hypothesis of depression: low synaptic serotonin → depression. SSRIs (selective serotonin reuptake inhibitors) like fluoxetine block serotonin reuptake → ↑ synaptic serotonin → antidepressant effect."),
  mkQ(824,"Reproduction","easy","The umbilical cord contains:",["Two umbilical arteries and one umbilical vein (total 3 vessels)","One artery and one vein","Lymphatic vessels and nerves only","Three arteries"],0,"Umbilical cord: 2 umbilical arteries (deoxygenated blood from fetus → placenta) + 1 umbilical vein (oxygenated blood from placenta → fetus) + Wharton's jelly. Connects fetus to placenta."),
  mkQ(825,"Endocrinology","medium","Calcitonin (from thyroid's parafollicular C cells) is ANTAGONISTIC to PTH because calcitonin:",["Raises blood calcium","Lowers blood calcium (inhibits osteoclasts, promotes renal excretion)","Raises blood glucose","Promotes bone resorption"],1,"Calcitonin: released when blood Ca²⁺ is HIGH → inhibits osteoclasts (reduces bone resorption), promotes renal Ca²⁺ excretion → lowers blood Ca²⁺. Antagonises PTH action."),
  mkQ(826,"Neurology","medium","INCORRECT about the nervous system:",["Sensory (afferent) neurons transmit signals from receptors to CNS","Motor (efferent) neurons transmit signals from CNS to effectors","Interneurons connect sensory and motor neurons within CNS","All CNS neurons can regenerate fully after injury"],3,"Most CNS neurons (brain and spinal cord) CANNOT regenerate after injury due to inhibitory factors in CNS environment (myelin-associated proteins, chondroitin sulphate proteoglycans). PNS axons CAN regenerate if soma intact."),
  mkQ(827,"Reproduction","medium","Progesterone is mainly responsible for:",["Triggering ovulation (that's LH)","Maintaining the uterine lining (endometrium) during pregnancy; produced by corpus luteum then placenta","Promoting follicle growth (that's FSH)","Initiating menstruation (that's progesterone withdrawal)"],1,"Progesterone (from corpus luteum initially, then placenta): maintains thick secretory endometrium (prevents menstruation), inhibits new follicle development, prepares breast for lactation, decreases uterine contractions."),
  mkQ(828,"Neurology","easy","The cerebellum is primarily responsible for:",["Memory formation","Higher cognitive functions","Coordination of voluntary movement, balance, and muscle tone","Vision processing"],2,"Cerebellum: coordinates voluntary movements (smooth, precise), maintains posture and balance, involved in motor learning. Damage → ataxia (unsteady gait), tremor, dysmetria (inaccurate movement)."),
  mkQ(829,"Endocrinology","easy","Melatonin is secreted by which gland, and it regulates:",["Anterior pituitary — growth","Pineal gland — circadian rhythm (sleep-wake cycle) and seasonal reproduction","Thyroid gland — metabolism","Adrenal gland — stress response"],1,"Melatonin: secreted by pineal gland in darkness (light suppresses secretion). Regulates circadian rhythm (sleep-wake cycle), seasonal breeding in animals, and pubertal development."),
  mkQ(830,"Reproduction","medium","The germ layers (ectoderm, mesoderm, endoderm) are established during:",["Cleavage (morula stage)","Blastula formation","Gastrulation","Neurulation"],2,"Gastrulation: blastula cells rearrange to form three primary germ layers. Ectoderm → skin, nervous system. Mesoderm → muscles, skeleton, heart, kidney, gonads. Endoderm → gut lining, liver, lungs, pancreas."),
];

// ── TEST 9 ──
const T9 = [
  mkQ(901,"Biochemistry","medium","Which of the following is a NON-reducing sugar (cannot reduce Fehling's solution)?",["Glucose","Fructose","Galactose","Sucrose (table sugar)"],3,"Sucrose = glucose + fructose linked C1-C2 glycosidic bond, blocking both anomeric carbons → no free aldehyde/ketone → non-reducing. Glucose, fructose, maltose, lactose ARE reducing sugars."),
  mkQ(902,"Biochemistry","medium","The TCA (Tricarboxylic Acid/Krebs) cycle begins when Acetyl-CoA combines with:",["Pyruvate","Oxaloacetate (OAA) to form Citrate","Alpha-ketoglutarate","Succinate"],1,"TCA cycle: Acetyl-CoA (2C) + Oxaloacetate (4C) → Citrate (6C) [catalysed by citrate synthase]. OAA is regenerated at the end of each cycle turn."),
  mkQ(903,"Biochemistry","medium","In which step of aerobic respiration is FADH₂ produced?",["Glycolysis (glucose → pyruvate)","Oxidative decarboxylation of pyruvate","TCA cycle: succinate → fumarate (succinate dehydrogenase step)","Electron transport chain"],2,"FADH₂: produced in ONE step of TCA cycle — succinate dehydrogenase converts succinate to fumarate, reducing FAD to FADH₂. Also produced in beta-oxidation of fatty acids."),
  mkQ(904,"Biochemistry","medium","The net gain of ATP from GLYCOLYSIS alone (per glucose molecule) is:",["2 ATP net (4 produced − 2 invested)","4 ATP gross","8 ATP","36 ATP"],0,"Glycolysis: 4 ATP produced (substrate-level phosphorylation) − 2 ATP consumed (activation energy) = NET 2 ATP + 2 NADH + 2 pyruvate per glucose. Under anaerobic conditions, this is the only ATP source."),
  mkQ(905,"Biochemistry","medium","Disulfide bonds (-S-S-) in proteins are formed between cysteine residues and are important for:",["Primary structure (peptide bonds)","Secondary structure (α-helix, β-sheet)","Tertiary and quaternary structure stabilisation","RNA-protein interactions"],2,"Disulfide bonds (formed by oxidation of two -SH groups) contribute to tertiary structure stability in extracellular proteins (e.g., insulin, antibodies, keratin). They maintain protein conformation."),
  mkQ(906,"Biochemistry","easy","The enzyme that catalyses the breakdown of H₂O₂ (a toxic byproduct of metabolism) in peroxisomes is:",["Catalase","Superoxide dismutase","Cytochrome P450","Peroxidase"],0,"Catalase: present in peroxisomes, breaks down H₂O₂ → H₂O + O₂. Peroxisomes in plant cells are also associated with photorespiration. Catalase is one of the fastest enzymes known."),
  mkQ(907,"Biochemistry","medium","Fatty acids are catabolised (broken down) for energy through the process of:",["Glycolysis","Beta (β)-oxidation in mitochondrial matrix","TCA cycle directly","Gluconeogenesis"],1,"Beta-oxidation: sequential removal of 2-carbon units from fatty acid chain → Acetyl-CoA + NADH + FADH₂. 16-carbon palmitate → 8 Acetyl-CoA (each enters TCA cycle). Fat yields more ATP per gram than carbohydrate."),
  mkQ(908,"Biochemistry","medium","The Na⁺/K⁺-ATPase pump maintains resting membrane potential by:",["Pumping 2 Na⁺ out and 3 K⁺ in (net neutral)","Pumping 3 Na⁺ OUT and 2 K⁺ IN per ATP (net positive charge out → cell interior negative)","Pumping equal Na⁺ and K⁺ in opposite directions","Pumping Na⁺ in and K⁺ out"],1,"Na⁺/K⁺ pump: active transport (uses ATP) — 3 Na⁺ pumped OUT + 2 K⁺ pumped IN per cycle → maintains Na⁺ gradient (high outside), K⁺ gradient (high inside), and resting potential (~-70 mV, inside negative)."),
  mkQ(909,"Biochemistry","easy","The type of glycosidic bond in CELLULOSE (making it non-digestible by most animals) is:",["α-1,4 bond (like starch)","α-1,6 bond (like glycogen branching)","β-1,4 bond","β-1,6 bond"],2,"Cellulose: β-1,4-glycosidic bonds between glucose units → straight chain → parallel chains form strong hydrogen bonds → microfibrils. Mammals lack cellulase (β-1,4-glucosidase) — cannot digest it."),
  mkQ(910,"Biochemistry","easy","ATP is called the 'universal energy currency' of cells because:",["It is found only in certain cells","It is the most energy-dense molecule","Energy stored in its high-energy phosphate bonds (esp. γ-phosphate) is easily transferred to power cellular reactions","It is easily synthesised from oxygen"],2,"ATP = adenosine triphosphate. Hydrolysis of γ-phosphate bond (ATP → ADP + Pi) releases ~7.3 kcal/mol free energy, driving endergonic (energy-requiring) reactions in cells."),
  mkQ(911,"Biochemistry","medium","Facilitated diffusion of glucose into most body cells uses which type of transporter?",["SGLT (sodium-glucose linked transporter — active)","GLUT (glucose transporter) proteins — passive, no energy","Na⁺/K⁺ ATPase","Aquaporins"],1,"GLUTs (GLUT1-4): passive facilitated diffusion — down glucose concentration gradient. GLUT4 in muscle/fat cells is insulin-dependent (insulin → GLUT4 insertion in membrane). No ATP required."),
  mkQ(912,"Biochemistry","medium","The Michaelis constant (Km) of an enzyme represents the substrate concentration at which the reaction velocity is:",["Zero","Maximum (Vmax)","50% of Vmax (half-maximum)","75% of Vmax"],2,"Km = [S] when v = Vmax/2. Low Km = high affinity (enzyme saturated at low [S]). High Km = low affinity. Used to compare enzymes and study inhibitors (competitive inhibitors ↑ apparent Km)."),
  mkQ(913,"Biochemistry","medium","The PRIMARY mode of CO₂ transport in blood (from tissues to lungs) is as:",["CO₂ dissolved in plasma (~7%)","Carbamate compounds bound to haemoglobin (~23%)","Bicarbonate ions (HCO₃⁻) in plasma (~70%)","All three equally"],2,"CO₂ transport: ~70% as HCO₃⁻ (converted by carbonic anhydrase in RBCs: CO₂+H₂O→H₂CO₃→H⁺+HCO₃⁻), ~23% as carbamates (Hb-NH-COOH), ~7% dissolved. At lungs, reaction reverses."),
  mkQ(914,"Biochemistry","medium","Which of the following is a competitive inhibitor of an enzyme?",["An inhibitor that permanently binds to the active site by covalent bond","An inhibitor that binds at the allosteric site changing enzyme shape","An inhibitor structurally similar to substrate that reversibly blocks the active site","A product that blocks enzyme activity irreversibly"],2,"Competitive inhibitor: structurally similar to substrate → competes for active site → reversible → can be overcome by ↑[substrate]. Vmax unchanged, Km increased. Example: malonate inhibits succinate dehydrogenase."),
  mkQ(915,"Biochemistry","hard","Photorespiration (wasteful O₂-consuming, CO₂-releasing process in C₃ plants) occurs because RuBisCO:",["Has catalase activity","Has oxygenase activity — fixes O₂ instead of CO₂ under high O₂/low CO₂ (hot conditions)","Is activated by O₂","Is denatured at high temperature"],1,"RuBisCO has both carboxylase AND oxygenase activities. Under hot, dry conditions (stomata close → CO₂ depleted, O₂ builds up) → RuBisCO fixes O₂ → photorespiration → energy waste. C₄ plants avoid this."),
  mkQ(916,"Biochemistry","medium","In muscle cells during intense exercise (anaerobic), pyruvate is converted to:",["Acetyl-CoA","Ethanol (like yeast fermentation)","Lactate (lactic acid) by lactate dehydrogenase","CO₂ and H₂O"],2,"Lactic acid fermentation (muscle): pyruvate + NADH → lactate + NAD⁺. This regenerates NAD⁺ (needed for glycolysis to continue). Lactate accumulation causes muscle fatigue. Later oxidised in liver (Cori cycle)."),
  mkQ(917,"Biochemistry","easy","Amino acids are linked to form polypeptide chains by which type of bond?",["Hydrogen bonds","Disulfide bonds","Peptide bonds (formed between -COOH and -NH₂ groups by condensation)","Ionic bonds"],2,"Peptide bond: formed between carboxyl (-COOH) of one amino acid and amino (-NH₂) group of next, with loss of water (condensation reaction). The resulting -CO-NH- bond has partial double bond character."),
  mkQ(918,"Biochemistry","medium","Which vitamin acts as a coenzyme in carboxylation reactions (e.g., pyruvate carboxylase in TCA)?",["Vitamin C (ascorbic acid — antioxidant)","Vitamin B12 (cobalamin — methyl transfer)","Biotin (Vitamin B7)","Thiamine (Vitamin B1 — TDP)"],2,"Biotin: covalently bound to carboxylase enzymes (pyruvate carboxylase, acetyl-CoA carboxylase). Functions as CO₂ carrier. Deficiency causes dermatitis, hair loss, neurological symptoms."),
  mkQ(919,"Biochemistry","medium","The process of gluconeogenesis (synthesis of glucose from non-carbohydrate precursors) occurs primarily in:",["Muscle (from glucose only)","Liver (and kidney cortex)","Fat cells (adipose tissue)","Brain (primary glucose consumer)"],1,"Gluconeogenesis: liver (primary) and kidney cortex synthesise glucose from: lactate (Cori cycle), glycerol (from triglyceride breakdown), alanine and other glucogenic amino acids. Maintains blood glucose during fasting."),
  mkQ(920,"Biochemistry","medium","INCORRECT statement about enzymes:",["They lower the activation energy of reactions","They are not consumed or permanently altered in reactions","They are specific to their substrates (lock-and-key / induced-fit)","Increasing temperature always increases enzyme activity"],3,"Enzyme activity increases with temperature up to the optimal temperature (usually 37-40°C for human enzymes). Above optimal, the enzyme is DENATURED (protein unfolds, active site distorted) — activity drops sharply."),
  mkQ(921,"Biochemistry","medium","In the electron transport chain, Complex IV (cytochrome c oxidase) performs which reaction?",["Oxidises NADH to NAD⁺","Pumps protons only","Transfers electrons from cytochrome c to O₂ (final electron acceptor), forming water","Converts ATP to ADP"],2,"Complex IV: accepts electrons from cytochrome c → transfers to O₂ → forms H₂O (2 H₂O per O₂). Also pumps 4 H⁺ per 2 electrons. Final step of ETC, consumes all O₂ in mitochondria."),
  mkQ(922,"Biochemistry","medium","Gap junctions in animal cells allow:",["Structural support between cells (desmosomes do this)","Direct electrical/chemical communication — ions and small molecules pass between cells","Watertight sealing (tight junctions do this)","Attachment to ECM (focal adhesions)"],1,"Gap junctions: protein channels (connexins) connecting cytoplasm of adjacent cells. Allow direct cell-to-cell communication: ions, cAMP, metabolites pass through. Important in cardiac muscle (synchronous contraction) and developing embryos."),
  mkQ(923,"Biochemistry","easy","The monomer unit of glycogen (and starch) is:",["Fructose","Galactose","Glucose","Sucrose"],2,"Glygocen (animal starch): polymer of glucose with α-1,4-glycosidic bonds in chain + α-1,6-glycosidic bonds at branch points every 8-12 residues. Stored in liver and muscle. Highly branched for rapid glucose release."),
  mkQ(924,"Biochemistry","hard","The P/O ratio refers to:",["Ratio of phospholipids to oxygen in membranes","Moles of ATP synthesised per atom of oxygen consumed in oxidative phosphorylation","Ratio of protein to oxygen in cells","None of the above"],1,"P/O ratio: moles of ATP produced per O atom consumed. NADH → ~2.5 ATP per O; FADH₂ → ~1.5 ATP per O. Used to calculate theoretical ATP yield per glucose (~30-32 ATP total in modern estimates vs classic 36-38)."),
  mkQ(925,"Biochemistry","medium","Which of the following correctly pairs a vitamin with its deficiency disease?",["Vitamin A — Beriberi","Vitamin D — Rickets (in children) / Osteomalacia (adults)","Vitamin B12 — Scurvy","Vitamin K — Night blindness"],1,"Vitamin D: promotes Ca²⁺ absorption from gut and bone mineralisation. Deficiency → Rickets (children: soft, deformed bones) or Osteomalacia (adults: soft bones). Vitamin A → night blindness. Vitamin B12 → pernicious anaemia."),
  mkQ(926,"Biochemistry","medium","Which process provides the energy for active transport (like Na⁺/K⁺ pump, proton pump)?",["Diffusion","Facilitated diffusion","ATP hydrolysis (direct) or proton gradient (indirect active transport)","Osmosis"],2,"Active transport requires energy (against concentration gradient). Primary active transport uses ATP directly (e.g., Na⁺/K⁺ ATPase). Secondary active transport uses electrochemical gradient generated by primary active transport."),
  mkQ(927,"Biochemistry","medium","In aerobic respiration, the proton motive force (PMF) across the inner mitochondrial membrane is used to:",["Synthesise NADH","Activate enzymes in the stroma","Drive ATP synthase (Complex V) to produce ATP","Pump electrons through the ETC"],2,"Proton motive force (chemiosmosis, Mitchell hypothesis): ETC pumps H⁺ into intermembrane space → H⁺ gradient → H⁺ flows back through ATP synthase (F₀F₁ ATPase) → ATP synthesised from ADP + Pi."),
  mkQ(928,"Biochemistry","medium","Lactose is a disaccharide composed of:",["Glucose + Glucose (that's maltose)","Glucose + Fructose (that's sucrose)","Glucose + Galactose","Fructose + Galactose"],2,"Lactose (milk sugar): β-galactose + glucose (β-1,4-glycosidic bond). Digested by lactase (β-galactosidase). Lactase deficiency → lactose intolerance (bloating, diarrhoea from bacterial fermentation of undigested lactose)."),
  mkQ(929,"Biochemistry","hard","Which statement about allosteric enzymes is TRUE?",["They follow simple Michaelis-Menten kinetics","They are inhibited by substrate","They show sigmoidal v vs [S] curves (cooperativity) and are regulated by molecules binding at sites other than active site","They are found only in prokaryotes"],2,"Allosteric enzymes: key regulatory enzymes (e.g., phosphofructokinase-1 in glycolysis). They have allosteric sites where activators/inhibitors bind → conformational change → changes enzyme activity. Show sigmoidal kinetics (cooperative)."),
  mkQ(930,"Biochemistry","medium","The secondary structure of proteins (alpha-helix and beta-sheet) is maintained by:",["Peptide bonds between amino acids","Disulphide bonds between cysteine residues","Hydrogen bonds between backbone C=O and N-H groups","Hydrophobic interactions between non-polar side chains"],2,"Secondary structure: regular, repetitive conformations (α-helix, β-sheet, β-turn) stabilised by backbone H-bonds between -C=O of one peptide bond and -N-H of another (3-4 residues away in α-helix, or between strands in β-sheet)."),
];

// ── TEST 10 ──
const T10 = [
  mkQ(1001,"Cell Biology","easy","Which organelle is responsible for sorting, modifying, and packaging proteins for secretion?",["Lysosome","Peroxisome","Golgi apparatus (cis → trans)","Rough ER (site of synthesis, not packaging)"],2,"Golgi apparatus: receives proteins from ER (cis face), modifies them (glycosylation, phosphorylation), sorts and packages into vesicles (trans face) for secretion, lysosomes, or retention."),
  mkQ(1002,"Animal Physiology","medium","The sinoatrial (SA) node is often called the 'pacemaker' of the heart because:",["It is the thickest wall of the heart","It regulates blood pressure","It spontaneously generates electrical impulses that initiate each heartbeat","It pumps blood most forcefully"],2,"SA node (right atrium wall): autorhythmic cells spontaneously depolarise ~70 times/min (resting) → initiates heartbeat → impulse → AV node → Bundle of His → Purkinje fibres → ventricles. Regulated by ANS."),
  mkQ(1003,"Genetics","easy","In ABO blood groups, which genotype produces blood group AB?",["IAIA (homozygous A)","IAi (heterozygous A)","IAIB (co-dominant — both A and B antigens)","IBi (heterozygous B)"],2,"ABO blood type: IA and IB alleles are codominant → IAIB = blood group AB (both A and B antigens on RBCs, neither anti-A nor anti-B antibodies). i allele is recessive."),
  mkQ(1004,"Ecology","medium","Primary ecological succession differs from secondary succession in that primary succession:",["Occurs faster","Has more species initially","Begins on a substrate with NO existing soil or community (bare rock, lava)","Requires less time to reach climax"],2,"Primary succession: starts from scratch (bare rock, sand dune, new volcanic island) — no soil, no seeds. Secondary succession: starts after disturbance where soil and seed bank remain (abandoned farmland, after fire)."),
  mkQ(1005,"Plant Physiology","medium","Stomata open when guard cells accumulate K⁺ (potassium ions) because:",["K⁺ makes guard cells rigid","K⁺ influx drives water in via osmosis → guard cells become turgid → stoma opens","K⁺ directly opens pores","K⁺ reduces CO₂ inside leaf"],1,"Stomatal opening mechanism: K⁺ actively pumped into guard cells (via H⁺-ATPase) → ↑ osmotic pressure → water follows by osmosis → turgor ↑ → guard cells bow outward → stoma opens."),
  mkQ(1006,"Evolution","medium","Darwin's theory of Natural Selection was partly inspired by reading the economist who described population growth outstripping food supply:",["Adam Smith","David Ricardo","Thomas Robert Malthus","John Stuart Mill"],2,"Malthus's 'Essay on Population' (1798): populations grow geometrically, food supply arithmetically → struggle for existence. Darwin applied this to: variation + heredity + overproduction → natural selection."),
  mkQ(1007,"Biotechnology","medium","A 'reporter gene' (like β-galactosidase or GFP) in a vector is used to:",["Code for the protein of interest","Confirm successful transformation of host cells (detectable marker)","Restrict unwanted DNA insertion","Replicate the vector"],1,"Reporter genes encode easily detectable products (blue/white colony selection with lacZ/β-gal; fluorescence with GFP; luminescence with luciferase). When foreign DNA disrupts the reporter gene, you can identify successful recombinants."),
  mkQ(1008,"Cell Division","easy","During which phase of the cell cycle is DNA replicated (chromosomes duplicated)?",["G1 phase (cell grows, prepares for S)","S phase (synthesis — DNA replication)","G2 phase (prepares for mitosis)","M phase (mitosis and cytokinesis)"],1,"S phase (DNA synthesis): each chromosome is replicated → each chromosome now consists of two identical sister chromatids joined at centromere. Also: centriole duplication begins."),
  mkQ(1009,"Neurology","easy","Which part of the brainstem controls vital involuntary functions including breathing, heart rate, and blood pressure?",["Cerebellum","Pons","Medulla oblongata","Midbrain"],2,"Medulla oblongata: contains vital autonomic centres — cardiovascular centre (heart rate, BP), respiratory centre (breathing rhythm), vasomotor centre. Damage = immediately fatal."),
  mkQ(1010,"Animal Kingdom","medium","Filter feeding (using baleen plates to filter krill from seawater) is the feeding strategy of:",["Great white shark","Eagle","Blue whale (Balaenoptera musculus)","Killer whale (Orca)"],2,"Blue whale: largest animal on Earth, feeds by gulp filter feeding — engulfs huge volumes of water → pushes through baleen plates (keratin) → krill trapped, water expelled."),
  mkQ(1011,"Biochemistry","easy","During photosynthesis, O₂ is released as a by-product from the photolysis (splitting) of:",["CO₂","Glucose","Water (H₂O) in the light reactions","ATP"],2,"Water photolysis (Hill reaction) in PSII: 2H₂O → 4H⁺ + 4e⁻ + O₂. The O₂ released by plants comes from water, NOT CO₂. O₂ is a by-product. The electrons replenish PSII's reaction centre."),
  mkQ(1012,"Immunity","medium","The complement system functions in immunity by:",["Repairing DNA damage in immune cells","Opsonising pathogens, triggering inflammation, and directly lysing bacteria via membrane attack complex (MAC)","Producing antibodies","Presenting antigens to T cells"],1,"Complement system: cascade of ~30 proteins. Functions: opsonisation (C3b marks pathogens for phagocytosis), chemotaxis (C3a, C5a attract phagocytes), direct lysis (MAC = C5b-9 pore in pathogen membrane)."),
  mkQ(1013,"Genetics","medium","The phenomenon where a heterozygous individual (Aa) shows a phenotype INTERMEDIATE between both homozygotes (AA and aa) is called:",["Codominance","Complete dominance","Incomplete dominance","Epistasis"],2,"Incomplete dominance: neither allele is completely dominant. RR = red, rr = white, Rr = PINK (intermediate). Phenotypic ratio from Rr × Rr = 1 red : 2 pink : 1 white. Example: snapdragon flower colour."),
  mkQ(1014,"Animal Physiology","medium","Which of the following correctly describes urine formation in the kidney?",["Glomerular filtration → selective tubular reabsorption → tubular secretion","Secretion → filtration → reabsorption","Reabsorption first, then filtration","No reabsorption occurs — everything filtered is excreted"],0,"Nephron function: (1) Glomerular filtration (ultrafiltration of plasma), (2) Selective tubular reabsorption (reclaims glucose, amino acids, most water), (3) Tubular secretion (adds H⁺, K⁺, drugs, toxins to filtrate)."),
  mkQ(1015,"Ecology","medium","A food web is more stable than a food chain because:",["It has fewer species","It follows the 10% energy law more strictly","Multiple feeding links allow alternative energy pathways if one species declines","It has less biodiversity"],2,"Food web stability: if one prey species declines, predators can switch to alternative prey. More links = more redundancy = greater ecosystem resilience. Single food chains are highly vulnerable to disruption."),
  mkQ(1016,"Cell Biology","medium","Which of the following is TRUE about osmosis?",["It requires energy (active transport)","Solutes move across the membrane","Water moves from HIGHER water potential (lower solute) to LOWER water potential (higher solute) across a semipermeable membrane","It moves material against concentration gradient"],2,"Osmosis: passive movement of water across semipermeable membrane from region of high water potential (low solute concentration) to low water potential (high solute concentration). No energy needed — driven by water potential gradient."),
  mkQ(1017,"Biotechnology","medium","RNA interference (RNAi) is used as a tool in plant biotechnology to:",["Amplify specific RNA sequences","Create double-stranded RNA (dsRNA) that silences specific pest genes, e.g. to protect tobacco from nematode infection","Replace defective genes","Sequence RNA molecules"],1,"RNAi application (OUAT relevant): dsRNA matching nematode essential gene → when nematode eats plant → dsRNA processed to siRNA in nematode → silences gene → nematode dies. Used in Bt-resistant strategies."),
  mkQ(1018,"Plant Physiology","medium","The light reactions of photosynthesis produce which products used in the Calvin cycle?",["CO₂ and H₂O","Glucose and O₂","ATP and NADPH (and O₂ as by-product)","ADP and NADP⁺ only"],2,"Light reactions (thylakoids): photolysis of H₂O → O₂ released; photosystems generate ATP (photophosphorylation) and NADPH; these products go to stroma for Calvin cycle to fix CO₂ into sugar."),
  mkQ(1019,"Evolution","hard","Disruptive selection acts AGAINST the average/intermediate phenotype, favouring both extremes. This can potentially lead to:",["Stabilising selection","Directional selection","Sympatric speciation (if extremes no longer interbreed)","No evolutionary change"],2,"Disruptive selection: example — black and white oyster catchers in heterogeneous rocky/sandy habitat (neither intermediate camouflage works). If extreme types mate assortatively → reproductive isolation → sympatric speciation."),
  mkQ(1020,"Animal Physiology","easy","The eustachian tube (pharyngotympanic tube) connects the:",["Outer ear to middle ear","Pharynx (nasopharynx) to the middle ear cavity","Inner ear to cochlea","Nasal cavity to the sinuses"],1,"Eustachian tube: equalises air pressure between middle ear and atmospheric pressure (important during altitude changes, swallowing). Connects nasopharynx to middle ear. Dysfunction → ear pain during flights, ear infections."),
  mkQ(1021,"Reproduction","medium","Which hormone initially maintains the corpus luteum (preventing menstruation) if fertilisation occurs?",["Estrogen (from follicle)","FSH (from pituitary)","hCG (human chorionic gonadotropin — from early placenta)","LH from pituitary"],2,"hCG: produced by trophoblast cells of implanted blastocyst → maintains corpus luteum → corpus luteum continues producing progesterone → endometrium maintained. hCG is detected by pregnancy tests."),
  mkQ(1022,"Microbiology","easy","Which bacterium is the most extensively studied and used model organism in molecular biology?",["Streptococcus pneumoniae","Staphylococcus aureus","Escherichia coli (E. coli)","Mycobacterium tuberculosis"],2,"E. coli K-12 strain: rapid growth (20 min doubling), cheap to culture, well-characterised genetics, easily transformed, produces many human proteins recombinantly. First organism whose genome was sequenced after bacteriophage."),
  mkQ(1023,"Cell Division","medium","A cell with 2n=46 enters meiosis. After meiosis I, each secondary oocyte/secondary spermatocyte contains:",["46 chromosomes (2n) — unchanged","23 chromosomes, each with 2 chromatids (n, but DNA = 2 copies)","23 single chromatids","92 chromatids"],1,"After meiosis I: homologous chromosomes are separated → each cell has 23 chromosomes. But each chromosome still has 2 sister chromatids joined at centromere (DNA content = 2C). Sister chromatids separate in meiosis II."),
  mkQ(1024,"Genetics","medium","INCORRECT statement about DNA:",["DNA is double-stranded with antiparallel strands","DNA carries genetic information as sequence of nucleotide bases","DNA contains ribose sugar","DNA is present in nucleus, mitochondria, and chloroplasts"],2,"DNA contains DEOXYRIBOSE sugar (2'-deoxyribose — lacks -OH at 2' carbon). RNA contains ribose (has -OH at 2'). This makes DNA more chemically stable — suitable for long-term genetic storage."),
  mkQ(1025,"Animal Physiology","medium","Which of the following is NOT a function of the liver?",["Synthesis of plasma proteins (albumin, clotting factors)","Bile production and secretion","Detoxification of drugs and hormones","Filtration of blood to produce urine (renal function)"],3,"Liver functions: bile production, plasma protein synthesis, urea synthesis (detox of ammonia), detoxification (drugs, alcohol, hormones), glycogen storage, gluconeogenesis, vitamin storage. Urine production = KIDNEYS."),
  mkQ(1026,"Ecology","easy","Biomass refers to:",["Total number of organisms per unit area","Total dry weight of organic matter in organisms per unit area","Total solar energy stored in an ecosystem","Amount of water in living organisms"],1,"Biomass: total dry weight (or energy equivalent) of living organisms in a given area. Decreases along food chain (pyramids of biomass are usually upright). Aquatic ecosystems: phytoplankton may have inverted biomass pyramid (rapid turnover)."),
  mkQ(1027,"Classification","medium","Kingdom Fungi is characterised by all of the following EXCEPT:",["Cell wall made of chitin","Heterotrophic — absorptive nutrition (saprotrophic or parasitic)","Eukaryotic organisation","Autotrophic — can photosynthesise"],3,"Fungi are HETEROTROPHS — they cannot photosynthesise. They obtain nutrients by secreting exoenzymes to digest food externally (extracellular digestion) and absorbing the products. Cell wall = chitin (unlike plants: cellulose)."),
  mkQ(1028,"Genetics","medium","Polygenic inheritance results in continuous variation because:",["Each gene has only 2 alleles","Multiple genes (each with additive small effects) control one trait → many phenotypic classes forming a continuous bell curve","All alleles are codominant","It involves sex-linked genes only"],1,"Polygenic traits (height, skin colour, intelligence, weight): controlled by many loci, each contributing a small additive effect. Result = continuous normal distribution of phenotypes. Influenced by both genes and environment."),
  mkQ(1029,"Immunity","medium","INCORRECT statement about the immune system:",["B lymphocytes produce antibodies after activation","T lymphocytes include CD4+ helper and CD8+ cytotoxic types","Antigens are foreign molecules (proteins, polysaccharides) that trigger immune responses","Memory cells produce faster and stronger immune response on RE-EXPOSURE due to faster antigen production by memory cells"],3,"Memory cells (B and T) respond faster on re-exposure because they already exist in large numbers and are primed to activate quickly — they do NOT produce antigens. Antigens are FOREIGN molecules from pathogens."),
  mkQ(1030,"Animal Physiology","medium","The normal ECG shows waves P, QRS, and T. Which wave represents ventricular depolarization?",["P wave (atrial depolarization/contraction)","Q wave only","QRS complex (ventricular depolarization/contraction — systole)","T wave (ventricular repolarization)"],2,"ECG: P wave = atrial depolarisation (SA → AV node). QRS complex = ventricular depolarisation (Bundle of His → Purkinje → ventricles contract). T wave = ventricular repolarisation (ventricles relax/diastole)."),
];

